local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[527] = { title = "Kampf um Hillsbrad", description = "Steht gefälligst stramm, wenn Ihr mit mir sprecht, $C.\n\nIch stehe unter direktem Kommando von Varimathras. Wir sollen der menschlichen Plage Einhalt gebieten, bis unsere Apotheker eine neue Pest entwickeln können.\n\nUnseren Informationen zufolge bietet Hillsbrad einen guten Angriffspunkt. Eure erste Aufgabe ist darauf gerichtet, die Nahrungsversorgung und Infrastruktur zu unterbrechen.\n\nBegebt Euch nach Westen. Überfallt die nördlichsten Höfe der Felder von Hillsbrad. Und stellt sicher, dass die Landeigner, Bauer Ray und Bauer Getz, ebenfalls exekutiert werden.", objectives = "Tötet 6 Landarbeiter von Hillsbrad, 6 Bauern von Hillsbrad, Bauer Ray und Bauer Getz und meldet Euch dann wieder bei Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[528] = { title = "Kampf um Hillsbrad", description = "Die Berichte vom Angriff auf die nördlichen Höfe haben die Stadtbevölkerung in Panik versetzt. Vorzüglich.\n\nUnsere Todespirscher melden, dass Arbeiter in die Felder ins südliche Hillsbrad flüchten. Diese Narren glauben doch tatsächlich, dass sie sich in den Obsthainen verstecken und so ihrer Verdammnis entkommen können.\n\nBeweist ihnen das Gegenteil, $N. Kehrt zu den Feldern von Hillsbrad zurück und macht die feigen Arbeiter ausfindig. Vernichtet sie im Namen der dunklen Fürstin.\n\nWeggetreten!", objectives = "Tötet 15 Arbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[529] = { title = "Kampf um Hillsbrad", description = "Die Menschen in Hillsbrad leisten unerwarteten Widerstand. Das Problem scheint darin zu bestehen, dass die Bewohner durch den örtlichen Schmied mit Waffen versorgt werden. Wir müssen alle Versorgungsmöglichkeiten abschneiden.\n\nEure Aufgabe ist es, Schmied Verringtan zu eliminieren. Tötet auch gleich seine Lehrlinge. Wenn Ihr schon dort seid, bringt auch gleich eine Eisenlieferung aus ihrem Vorratslager mit zurück. Nach der Eroberung von Hillsbrad werden diese Vorräte uns gelegen kommen, wenn wir mit der Verwüstung von Southshore beginnen.", objectives = "Tötet Schmied Verringtan und 4 Schmiedelehrlinge von Hillsbrad.\n\nBesorgt eine Eisenlieferung und erstattet Bericht bei Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[530] = { title = "Rache eines Ehemanns", description = "Valdred, einst ein guter Freund von mir, ist der Mörder meiner Frau. Auch wenn ich keine Trauer empfinden kann, so sehne ich mich doch nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.\n\nDas Letzte, was ich hörte, war, dass er sich im südlichen Silberwald beim Greymane-Wall aufhält und in das Königreich von Gilneas flüchten will.", objectives = "Tötet Valdred Moray.\n\nBringt seine Hände zu Raleigh Andrean nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[531] = { title = "Vyrins Rache", description = "Licht! Bringt solche Dinge nicht in die Lodge... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!\n\nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, nu wirklich nicht!", objectives = "Bringt Old Sootys Kopf zu Vyrin Swiftwind in die Weitschreiter-Lodge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[532] = { title = "Kampf um Hillsbrad", description = "Hillsbrad ist ein einziges Chaos und wir sind der Meinung, dass die Stadt bald fallen wird. Nichtsdestotrotz müssen wir weiterhin an unserer Ruchlosigkeit festhalten bis der menschliche Abschaum ein für alle Mal von diesem Vorgebirge verschwunden ist.\n\nTrotz ihrer überwältigenden Verluste sammeln die Menschen sich weiterhin um ihre Führungskraft und kämpfen weiter. Wir müssen ihren Anführer, Magistrat Burnside eliminieren und mit ihm den ganzen Stadtrat. Zerstört ihr heißgeliebtes politisches Dokument, die Proklamation von Hillsbrad, gleich mit. Und wenn Ihr schon dabei seid, stehlt das Stadtregister.", objectives = "Tötet Magistrat Burnside und 5 Ratsherren von Hillsbrad. Zerstört die Proklamation von Hillsbrad. Stehlt das Stadtregister von Hillsbrad. Meldet Euch danach bei Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[533] = { title = "Unterwanderung", description = "Endlich haben wir eine Spur und können nach Hinweisen auf Gol'dirs Aufenthaltsort suchen. Die Menschen haben ihn immer wieder umquartiert, aber wir konnten unsere Suche einengen und konzentrieren uns jetzt auf das große Syndikatlager nördlich von hier.\n\nBegebt Euch dorthin, $n, und beschafft alle Informationen, an die Ihr herankommen könnt.", objectives = "Holt Informationen über Gol'dirs Aufenthaltsort für Krusk in Tarrens Mühle ein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[535] = { title = "Valik", description = "Arrrgh... Verletzt, sterbend und den Feind direkt vor Augen...\n\nDa Ihr mich ja sowieso töten werdet, könntet Ihr mir da vielleicht zuvor ein Southshore-Starkbier bringen - Euresgleichen trinkt doch auch, oder? - und ich werde Euch sagen, was Ihr wissen wollt.", objectives = "Bringt einen Becher mit Southshore-Starkbier zu Valik in das Lager des Syndikats.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[536] = { title = "Die Küste entlang", description = "Von der Stadtwache von Stormwind nach Southshore versetzt, eine Stadt, die man gleich wieder verlassen sollte... wie's aussieht. Der Gestank vom Hafen Tag und Nacht.\n\nGanz zu schweigen vom alten Redpath... Will, dass ich mich um die Murlocs kümmere. Ha! \n\nKann mich kaum aufraffen, die Unterschlüpfe dieser übergroßen Fische unten am Weststrand aufzusuchen. Wenn Ihr für mich gehen und Euch um sie kümmern würdet, wäre ich Euch sehr dankbar.", objectives = "Tötet 10 Gezeitenjäger der Fetzenflossen und 10 Orakel der Fetzenflossen für Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[537] = { title = "Der Dunkle Rat", description = "Der Brief, den Ihr mir gebracht habt, wurde von einem Wesen geschrieben, das sich selbst Nagaz nennt, ein Mitglied der Arguswacht. Ich weiß nicht, was diese Arguswacht ist, aber wenn sie mit dem Syndikat zusammenarbeiten, dann sind sie eine Bedrohung.\n\nIch möchte, dass Ihr Nagaz und die Schattenmagier der Arguswacht, die in diesem Brief erwähnt werden, findet. Ihr sollt sie finden und dann töten.\n\nSucht im Oberland, wo das Syndikat am stärksten ist. Es liegt nördlich von Strahnbrad.\n\nMit etwas Glück könnt Ihr die Abgesandten der Arguswacht dort finden.", objectives = "Tötet 4 Schattenmagier der Arguswacht.\n\nBringt den Kopf von Nagaz zu Magistrat Maleb nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[538] = { title = "Süderstade", description = "$N. Wenn Ihr einer langen Reise nicht abgeneigt seid, dann habe ich eine neue Aufgabe für Euch, Stormwind erneut bei der Bestückung seiner Bibliothek behilflich zu sein.\n\nDas alte Königreich von Alterac ist nach dem großen Krieg gefallen und es besaß eine umfangreiche Büchersammlung. Es ist eine große Tragödie, dass die Stadt verfallen ist, aber es ist weitaus tragischer, dass all ihr Wissen verloren geht! Wir müssen retten, was zu retten ist.\n\nSouthshore liegt den Ruinen von Alterac am nächsten. Begebt Euch dorthin und sprecht mit dem Meister der Lehren Dibbs. Er kann Euch den Weg zu den Ruinen erklären und welche Bücher dort zu finden sind.", objectives = "Sprecht mit dem Meister der Lehren Dibbs in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[539] = { title = "Kampf um Hillsbrad", description = "Das Stadtregister von Hillsbrad deutet an, dass der Azurschacht unter der Kontrolle der Allianz steht. Außerdem ist die Mine eine erstklassige Quelle für Eisenerz für die Waffenkammern der Allianz.\n\nAuch wenn wir der Stadt von Hillsbrad einen entscheidenden Schlag versetzen konnten, unterstützt und beschützt die Allianz den Azurschacht immer noch aufs Äußerste.\n\nDie Mine liegt genau im Süden von Hillsbrad. Begebt Euch dorthin und tötet den Großknecht, einen Menschen namens Bonds. Tötet auch gleich seine Minenarbeiter. Das sollte der Allianz ein deutliches Zeichen setzen.", objectives = "Tötet Großknecht Bonds sowie 10 Minenarbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[540] = { title = "Wissen bewahren", description = "Diese barbarischen Oger haben sich in den Ruinen von Alterac ausgebreitet und es schüttelt mich bei dem Gedanken, was sie mit den wertvollen Büchern dort anstellen könnten. Ihr müsst retten, was immer Ihr könnt!\n\nGeht zu den Ruinen von Alterac und sucht dort nach Folianten, die die Oger gestohlen haben. Nehmt, was immer Ihr finden könnt, und bringt alles zu mir, aber sucht insbesondere ein ganz bestimmtes Buch: Der Arm von Gri'lek. Es enthält alte Trolllehren, die ich erlernen muss. Die Ruinen von Alterac waren der letzte bekannte Ort, an dem es ein intaktes Exemplar dieses Buches geben soll.", objectives = "Bringt 5 geborgene Folianten und das abgenutzte Lederbuch, das 'Der Arm von Gri'lek' enthält, zum Meister der Lehren Dibbs nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[541] = { title = "Kampf um Hillsbrad", description = "Zwerge helfen Menschen? Diese verdammten, dreckigen kleinen Bestien.\n\nWir werden die Stärke dieser so genannten Allianz testen. Wir werden ja sehen, wie sehr diese kleinen Wadenbeißer den Menschen noch helfen wollen, nachdem sie unseren Zorn zu spüren bekommen haben. Wir wissen ganz genau, wo sie in diesem Gebiet ihre Hochburg haben.\n\nSie haben eine Kaserne namens Dun Garok im südöstlichen Hillsbrad entlang des Thoradin-Walls errichtet. Die letzte Order in diesem Kampf ist die Belagerung von Dun Garok, $C. Captain Eisenberg, ihr Anführer muss sterben.", objectives = "Begebt Euch nach Dun Garok, tötet 10 Gebirgsjäger, 8 Scharfschützen, 4 Priester sowie Captain Eisenberg und erstattet danach Bericht bei Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[542] = { title = "Rückkehr zu Milton", description = "Ich werde einige Zeit benötigen, um das Buch Der Arm von Gri'lek zu studieren, das Ihr mir gebracht habt. Ich bin sicher, Milton kann es kaum erwarten, die anderen geborgenen Bücher in die Sammlung von Stormwind zu integrieren.\n\nHier sind die Bücher, die Ihr aus den Ruinen von Alterac mitgebracht habt, verpackt und katalogisiert. Bringt sie zu Milton Sheaf in Stormwind und ich versichere Euch, dass er sehr dankbar sein wird.", objectives = "Bringt die Folianten von Alterac zu Milton Sheaf nach Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[543] = { title = "Die Perenolde-Tiara", description = "Die Perenolde-Tiara ist ein altes Erbstück der \"Edlen\" von Perenolde - der Herrscherfamilie von Alterac, bevor das Königreich verfiel. Es heißt, dass sie von Meisterjuwelieren in Ironforge hergestellt und mit den schönsten Smaragden besetzt wurde.\n\nAls Alterac zerstört wurde, ging die Tiara verloren, aber Gerüchten zufolge soll ein Ogermagier, Grel'borg der Horter, die Tiara gefunden haben und jetzt in den Ruinen von Alterac auf der Suche nach weiteren Schätzen umherwandern.\n\nWir möchten, dass Ihr die Tiara für uns beschafft.", objectives = "Bringt die Perenolde-Tiara zu Remington Ridgewell nach Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[544] = { title = "Gefängnis-Einbruch", description = "Eigentlich kam ich zu Forschungszwecken nach Tarrens Mühle, aber jetzt muss ich eine Krise verhindern. Wisst Ihr, vier Verlassene sind vor einigen Monaten aus Undercity geflohen. Sie haben ihren Brüdern den Rücken zugekehrt, aber was viel schlimmer ist... sie haben die dunkle Fürstin bestohlen.\n\nDiese Diebe sind in ein gesichertes Gewölbe eingebrochen und haben vier Artefakte gestohlen; Gegenstände, die unsere Apotheker für bestimmte Studien benötigen. Sylvanas will, dass diese Artefakte zurückgebracht werden.\n\nDie Diebe sind aus Undercity nach Dalaran geflohen und diese Hexer haben sie in Quarantäne in das Lordamere-Internierungslager gesteckt.", objectives = "Findet diese Verräter, sammelt ihre Artefakte ein und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[545] = { title = "Patrouillen von Dalaran", description = "Die Hexer von Dalaran haben eine riesige, magische Kuppel um ihren Stadtkern errichtet. Einige glauben, dass es zum Schutz gegen die Gewalt unserer Zeit gemacht wurde, andere wiederum sagen, dass sie einfach Ruhe zum Studieren und Pläneschmieden haben wollen.\n\nMir persönlich ist der Grund egal. Aber mir ist nicht egal, dass die verfallenen Vororte der Stadt, die außerhalb der Kuppel liegen, möglicherweise wertvolle magische Schätze beherbergen.\n\nAber dieses Gebiet wird von den Hexern und ihren Elementarsklaven patrouilliert.\n\nAlso jagt sie und kehrt erst zurück, wenn ihre Anzahl einigermaßen reduziert worden ist.", objectives = "Tötet 6 Beschwörer von Dalaran sowie 12 Elementarsklaven und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[546] = { title = "Andenken des Todes", description = "Ich habe gehört, Ihr wurdet von Darthalia eingezogen, um Krieg gegen die Menschen von Hillsbrad zu führen. Ich bin ganz grün vor Neid...\n\nIhr habt den ganzen Spaß... Menschen erschlagen, die Stadt plündern, Unschuldige terrorisieren..., und ich stecke hier fest und darf in Tarrens Mühle Wache schieben.\n\nVielleicht habt Ihr ja etwas Mitleid mit einer alten Todeswache wie mir? Wisst Ihr, ich sammle nämlich menschliche Schädel. Und Ihr werdet eine recht lange Zeit gegen Menschen kämpfen. Bringt mir im Verlauf Eures langen Kampfes 30 Schädel, und ich werde Euch für Eure Mühe entlohnen.", objectives = "Todeswache Samsa aus Tarrens Mühle will 30 menschliche Schädel aus Hillsbrad.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[547] = { title = "Humberts Schwert", description = "Hochexekutorin Darthalia hat mich hergeschickt, um Dun Garok aus der Ferne zu beobachten. Ich hatte mein Lager gerade außer Sichtweite aufgeschlagen. Am Morgen, als ich Wasser kochen wollte, ging ich Feuerholz sammeln.\n\nAls ich ins Lager zurückkam, entdeckte ich, dass meine Ausrüstung verschwunden war.\n\nAnscheinend waren ein paar Zwergenspäher von Dun Garok vorbeigekommen und hatten alles mitgenommen. Ich brauche mein Schwert! Wenn Ihr es für mich zurückholen könntet, wäre ich Euch sehr dankbar. So viele Zwerge hier... es wird ganz schön schwierig sein, den kleinen dreckigen Dieb zu finden, der es gestohlen hat.", objectives = "Bringt das Schwert von Todeswache Humbert aus Dun Garok zu ihm nach Tarrens Mühle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[549] = { title = "GESUCHT: Syndikatspersonal", description = "In Lady Sylvanas Namen sollen alle Mitglieder der Organisation, die sich das Syndikat nennt, getötet werden. Diejenigen, die bereits gefangen genommen wurden, werden gemeinschaftlich hingerichtet. Wir wissen, dass sie sich im Moment in den Ruinen der Burg Durnholde im Südosten von Tarrens Mühle sammeln.\n\nFür alle diejenigen, die Beweise ihrer Taten zu Hochexekutorin Darthalia bringen, ist eine reiche Belohnung ausgesetzt.", objectives = "Tötet 10 Schurken des Syndikats und 10 Wachmänner des Syndikats. Kehrt danach zu Hochexekutorin Darthalia nach Tarrens Mühle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[550] = { title = "Kampf um Hillsbrad", description = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht von Hillsbrad gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.\n\nBringt die versiegelte Belobigung zu Varimathras nach Undercity. Geht erhobenen Hauptes, $C.", objectives = "Bringt Darthalias versiegelte Belobigung zu Varimathras nach Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[551] = { title = "Das Verhexte Pergament", description = "Dieses Pergament ist mit einer Verzauberung versehen, die es unlesbar macht. Nur ein Wort oben am Blattanfang ist lesbar:\n\n\n Nagaz\n\n", objectives = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[552] = { title = "Helculars Rache", description = "Meister Helcular hatte seine Transformation in einen Lich fast vollständig abgeschlossen, als ein menschlicher Lynch-Mob seinen rituellen Unterschlupf in den Hügeln entdeckte und ihn brutal ermordete. Was die Angelegenheit noch schlimmer macht, ist, dass sie seinen Leichnam auf dem Friedhof von Southshore begraben haben.\n\nDiese Missachtung eines großen Hexers ist einfach nicht akzeptabel. Als sein Lehrling werde ich dafür sorgen, dass der Regen der Rache auf Southshore fallen wird.\n\nAber zuerst benötigen wir Helculars Rute. Yetis befinden sich jetzt in seinem rituellen Unterschlupf. Bestimmt hat sich eine dieser Bestien die Rute angeeignet.", objectives = "Holt Helculars Rute von dem Yeti und bringt sie zu Novize Thaivand nach Tarrens Mühle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[553] = { title = "Helculars Rache", description = "Hier, nehmt die Rute von Helcular. Ihr werdet sie brauchen.\n\nHelcular stellte 3 zeremonielle Scheiterhaufen als Teil seines mächtigsten Zaubers auf. Die Flamme von Azel und die Flamme von Veraz liegen in den Vorgebirgshöhlen. Die Flamme von Uzel liegt in einer Höhle über diesen Höhlen, weiter nördlich in den Bergen.\n\nDie Rute von Helcular muss mit jeder der drei Flammen aufgeladen werden. Sobald das Ritual abgeschlossen ist, stoßt Ihr die Rute in Helculars Grab in Southshore, der streng bewachten Menschen-Stadt im Süden. Die Rache wird unser sein!", objectives = "Ladet die Rute von Helcular mit der Macht der Flamme von Azel, der Flamme von Veraz und der Flamme von Uzel auf.\n\nStoßt die aufgeladene Rute in Helculars Grab in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[554] = { title = "Stormpikes Entschlüsselung", description = "Ausgrabungsleiter Stormpike ist ein Meister der Dechiffrierung und Entschlüsselung. Wenn Ihr das Pergament, das Ihr gefunden habt, zu ihm bringt, kann er mit etwas Glück herausfinden, was darin steht. Im Moment studiert Stormpike im Ausgrabungsleiter-Hauptquartier in Ironforge.\n\nWenn Ihr ihn seht, richtet ihm aus, dass Ihr mit mir gesprochen habt, - ich habe ihm in letzter Zeit einiges zu tun gegeben.", objectives = "Bringt das verhexte Pergament zu Ausgrabungsleiter Stormpike nach Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[555] = { title = "Milde Schildkrötensuppe", description = "Wenn es etwas Wissenswertes über Southshore gibt, dann dass wir hier die beste Küche nördlich von Stormwind haben!\n\nNehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von Dunkelhain hergekommen sind, nur um eine Schüssel voll davon zu kosten. Da wir gerade davon sprechen, in letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis kurz hinter Dalaran an den Lordameresee gereist, um Schnappkiefer zu jagen, aber das ist jetzt zu gefährlich. Wenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern aus dem Norden bringt und dazu noch feine Gewürze, dann werd ich eine kochen!", objectives = "Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Küchenchef Jessen nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[556] = { title = "Steinmarken", description = "Ein bemerkenswertes Talent der Hexer von Dalaran ist ihre Vertrautheit mit den Elementaren: mächtige Kreaturen aus anderen Dimensionen. Die Hexer benutzen magische Marken als Mittel, diese Elementare zu kontrollieren. Magus Voidglare hätte gern einige dieser Marken, damit er sie studieren kann.\n\nBegebt Euch auf das Gebiet der Hexer von Dalaran, westlich von Hillsbrad, und sammelt die Marken ein.\n\nJeder Einwohner von Dalaran hat solche Marken, aber ich schlage vor, dass Ihr im Internierungslager auf die Suche geht. Dort ist es sicherer als in Dalaran selbst.", objectives = "Bringt 10 abgenutzte Steinmarken zu Bewahrer Bel'varil nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[557] = { title = "Armschienen der Bindung", description = "Der Magus wird die Steinmarken, die Ihr gesammelt habt, einige Zeit lang intensiv untersuchen, aber ich weiß, dass er später mit Bestimmtheit auch Exemplare ihrer Gegenstücke haben will: Armschienen der Bindung. Diese befinden sich an den Handgelenken von echten Elementaren und binden sie in die Dienste der Magier.\n\nMacht Jagd auf Elementare in den Ruinen von Dalaran und sammelt ihre Armschienen der Erdbindung, und der Magus wird sehr erfreut sein.", objectives = "Bringt 4 Armschienen der Erdbindung zu Bewahrer Bel'varil nach Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[558] = { title = "Jainas Autogramm", description = "Ich habe gehört, dass Lady Jaina Prachtmeer aus Theramore eine der größten Heldinnen ist, die die Allianz je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Allianz werden!\n\nKennt Ihr Jaina, $n? Tut Ihr mir einen Gefallen? Kriege ich ein Autogramm von ihr? Ich weiß gar nicht, wie ich sie ansprechen soll, und wahrscheinlich ist sie sowieso viel zu beschäftigt, um mich zu beachten... aber was ist mit Euch? Ihr seid doch genau wie sie ein Abenteurer! Euch gibt sie bestimmt ein Autogramm!\n\nBitte, $n. Bitte...", objectives = "Reist nach Theramore und versucht für Euren Schützling ein Autogramm von Lady Jaina Prachtmeer zu ergattern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[559] = { title = "Farrens Beweis", description = "Was haltet Ihr davon, $N? Redpath war nicht zufrieden mit den ganzen Murlocs, die wir getötet haben - seid nur nicht so bescheiden, Ihr wart ja auch dran beteiligt. Jetzt verlangt er von mir, dass ich ihren Tod beweise und kalte, schleimige Murlocköpfe abhacke und sie ihm bringe, um seine Anerkennung zu erlangen.", objectives = "Sammelt 10 Murlocköpfe von den Murlocs am Weststrand für Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[560] = { title = "Farrens Beweis", description = "Wisst Ihr, $n, ich würde die Köpfe am liebsten gar nicht anfassen... Da Ihr sie nun schon mal angefasst habt, würde es Euch sehr viel ausmachen, sie zu Redpath zu bringen?", objectives = "Bringt den Sack mit den Murlocköpfen zu Marshal Redpath nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[561] = { title = "Farrens Beweis", description = "Bitte informiert Lieuntenant Orinelle über meinen Wunsch, er möge seine Aufmerksamkeit erneut auf die Nagaplage am Oststrand richten. Sobald er Resultate erzielt hat, soll er persönlich bei mir Bericht erstatten.", objectives = "Sprecht mit Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[562] = { title = "Sturmwind Ho!", description = "Mein ehemaliger Mentor bei der Stadtwache von Stormwind hat mir eine Nachricht zukommen lassen, dass sich das Oberkommando der Allianz langsam Sorgen macht um die Bedrohung, die von den Naga ausgeht. Er hat gehört, dass es gute Aussichten auf eine Beförderung - oder zumindest Versetzung - für jeden gibt, der sich in dieser Angelegenheit als hilfreich erweist.\n\nEs gibt da nur ein winzigkleines Problem... Ich schaff die Naga nicht, $N. Klar, ich kann eine Kneipenschlägerei auflösen, oder einen aggressiven Bettler wegschaffen, aber die Naga sind einfach zu viel für mich. Ihr müsst mir helfen, $N!", objectives = "Tötet 10 Küstenjäger der Säbelflossen und 10 Sirenen der Säbelflossen für Lieutenant Farren Orinelle in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[563] = { title = "Versetzungen", description = "Es dürfte kein Problem sein, meinen Bericht zu beachten. Der neue Captain der Wachen, Major Samuelson, war mein Mentor, während ich in Stormwind stationiert war. Der Bericht sollte ihm mehr als genug Grund geben, mich wieder in die Stadt zu versetzen. Aber ich brauche Euch, damit Ihr meinen Bericht zu ihm bringt... der alte Redpath soll nichts davon mitkriegen.", objectives = "Bringt Farrens Bericht zu Major Samuelson in die Burg Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[564] = { title = "Teure Bedrohung", description = "Nix macht mich wütender als wenn ich diese schönen Pferdchen verlieren tu. Und glaubt's mir, wir hab'n 'ne ganze Menge verloren, an die eklichen untoten Unholde, das verdammte Syndikatsgesocks und all die anderen tunichgute Schurken, die hier so rumlaufen tun.\n\nAber ich schwör beim Grab von mein alten Opa, 'ne größere Gefahr für uns're Pferdchen als die vonne Berglöwen in Alterac tut's nich' geben tun. Komm' alle Nase lang vonne Berge runner und machen mir dat Leben schwer.\n\nUnd Ihr seid also 'n Held? Dann geht mal und tut was dagegen unternehm' tun!", objectives = "Darren Malvew aus Southshore will, dass Ihr 8 Berglöwen und 10 titanische Berglöwen tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[565] = { title = "Bartolos Yetifellumhang", description = "Ich, der große Bartolo, werde für Euch den weltberühmten, allianzweit bekannten Yetifellumhang anfertigen.\n\nIch wette mit Euch: Auch wenn Ihr die ganze Welt bereist, findet Ihr keinen besseren Umhang. Oh, wartet mal, was ist das, kleiner $R? \"Bartolo, es gibt keinen feineren Umhang!\" Ja, ja! Das habe ich schon öfter gehört.\n\nBartolo benötigt einen Wollstoffballen, einen Umhang des Hügelwächters von einem geschickten Lederer, feinen Faden und natürlich Yetifell. Bringt mir diese Dinge und Ihr werdet ein glücklicher Kunde!", objectives = "Bringt Bartolo Ginsetti in Southshore einen Wollstoffballen, einen Umhang des Hügelwächters, feinen Faden und 10 Haufen Yetifell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[566] = { title = "GESUCHT: Baron Vardus", description = "Laut Befehl der Hochexekutorin Darthalia wird der unter dem Namen Baron Vardus bekannte Mensch wegen Verbrechen gegen die Verlassenen gesucht. Vardus ist bekannt als hochrangiges Mitglied der Organisation, die sich das Syndikat nennt.\n\nZuletzt wurde er im Oberland des Alteracgebirges im Norden von Tarrens Mühle gesehen.\n\nEr soll getötet werden. Für den Erhalt der Belohnung müssen Beweise seines Todes zu Hochexekutorin Darthalia gebracht werden.", objectives = "Tötet Baron Vardus und bringt seinen Kopf zu Hochexekutorin Darthalia in Tarrens Mühle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[567] = { title = "Gefährlich!", description = "Gefährlich!\n\nDie folgenden Menschen aus Hillsbrad werden als gefährlich erachtet. Ein Kopfgeld ist von Hochexekutorin Darthalia auf sie ausgesetzt worden.\n\nAmtmann Horatio Whitesteed. Gesucht wegen Mordes an Todeswache Toma.\n\nBürger Wilkes. Gesucht wegen Mordes an Apotheker Eli.\n\nMinenarbeiter Hackett. Gesucht wegen Mordes an Todespirscher Fry.\n\nBäuerin Kalaba. Gesucht wegen hinterhältigem Überfall auf Vorräte von Undercity.\n\nJeder dieser Feinde hat sich versteckt und wird nur sehr schwer zu finden sein. Auf die Nachricht ihres Todes wird eine Belohnung gewährt.", objectives = "Hochexekutorin Darthalia in Tarrens Mühle hat ein Kopfgeld auf Amtmann Horrace Whitesteed, Bürger Wilkes, Minenarbeiter Hackett und Bäuerin Kalaba ausgesetzt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[568] = { title = "Die Verteidigung von Grom'gol", description = "Throm-ka, $C!\n\nEure Ankunft in Grom'Gol kommt wahrlich zur rechten Zeit. Als Kommandant des Kriegshäuptlingsstützpunkts hier im Dschungel bin ich durch meine Ehre gebunden und verpflichtet, die Sicherheit aller Mitglieder der Horde zu gewährleisten. Unsere Aufgabe, eine sichere Versorgungskette nach Stonard zu gewährleisten wird durch einige der örtlichen Einwohner schwer behindert.\n\nIch gebe Euch den Auftrag, die Raptorpopulation außerhalb Grom'gols zu reduzieren. Sobald Ihr nennenswerte Fortschritt erzielt habt, erstattet mir Bericht und Ihr erhaltet einen neuen Auftrag.", objectives = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 15 Schmetterschwanzraptoren tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[569] = { title = "Die Verteidigung von Grom'gol", description = "Als wir in diesem Dschungel ankamen, hatten wir nicht vor, die hier ansässigen Stämme zu bekämpfen. Unsere Mission, Stonard zu versorgen, hat höchste Priorität. Aber es gibt Komplikationen. Eine hier ansässige Gruppe von Ogern hat die Ruinen von Mizjah im Südosten von Grom'gol besetzt. Trotz unserer Warnungen überfallen sie weiterhin unsere Nachschubkarawanen.\n\nIch beauftrage Euch hiermit, Euch mit diesen unkooperativen Ogern auseinander zu setzen.\n\nReist zu den Ruinen und versucht, sie aus diesem Gebiet zu vertreiben. Das sollte ihnen zumindest ein eindeutiges Zeichen setzen.", objectives = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 10 Ogerschläger und 5 Ogerhexendoktoren tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[570] = { title = "Mok'Thardins Verzauberung", description = "Die Macht der Dschungelmagie muss erkannt und kann dann von der Horde genutzt werden. Meine Rituale waren bislang erfolgreich. Ich kann sehr mächtige Verzauberungen wirken. Für Euch, mutiger $C, werde ich einen wirklich ganz besonderen Gegenstand herstellen.\n\nBringt mir einige Schattentatzenpantherkrallen und den Fangzahn einer Tigerin. Es darf aber nicht irgendein Fangzahn sein. Er muss sich in einem makellosen Zustand befinden.\n\nDiese Bestien lauern im gesamten Dschungel, aber Ihr könnt einige ganz in der Nähe finden. Überquert den Fluss von den Mizjah-Ruinen aus in südöstlicher Richtung.", objectives = "Scharfseher Mok'thardin im Basislager von Grom'gol will 8 Schattentatzenkrallen und einen makellosen Tigerinnenfangzahn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[571] = { title = "Mok'Thardins Verzauberung", description = "Was ich nun von Euch benötige, ist sehr schwer zu bekommen.\n\nIch benötige ein magisches Band, um all diese Federn, Krallen und den makellosen Fangzahn zu befestigen. Nur die Sehne eines alten Gorillas ist dazu geeignet.\n\nEine solche könnt Ihr nur von einem alten Nebeltalgorilla bekommen. Sie sind oft auf Nahrungssuche im Osten von Booty Bay.\n\nDie Sehne muss in vollkommenem Zustand sein. Ihr werdet wahrscheinlich mehrere Tiere töten müssen, bis Ihr genau das erhaltet, was ich benötige, aber das ist es in jedem Fall wert.", objectives = "Bringt die Sehne eines alten Gorillas zu Scharfseher Mok'thardin nach Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[572] = { title = "Mok'Thardins Verzauberung", description = "Die Dinge, die Ihr von den katzenartigen Bestien des Tales gesammelt habt, sind nur die erste Voraussetzung für einen machtvoll verzauberten Gegenstand. Diese Dschungelornamente, in Verbindung mit meinem Schamanenritual, werden Euch mit einem äußerst nützlichen Werkzeug versehen, mit dessen Hilfe Ihr der Horde und dem Kriegshäuptling beistehen könnt.\n\nAber jetzt müsst Ihr für mich einige Dschungelpirscherfedern sammeln. Für gewöhnlich tragen die Bestien diese Federn an ihren Armbändern. Ihr findet einen Stamm dieser Raptoren direkt südlich von Grom'gol, nicht weit von der großen Arena.", objectives = "Bringt 10 Dschungelpirscherfedern zu Scharfseher Mok'thardin nach Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[573] = { title = "Mok'Thardins Verzauberung", description = "Es fehlt nun nur noch ein Reagenz, um die Verzauberung zu vervollständigen.\n\nIm Süden, nahe der Westküste, liegt ein Heiliger Quell, hoch über den Steilhängen. Dieser Quell ist das Objekt großer Konflikte zwischen religiösen und mystischen Gelehrten. Jede einzelne Gruppe in Azeroth vertritt die Auffassung, dass das Quellwasser nur für das eigene Volk göttlich gemacht wurde.\n\nMeine letzte Aufgabe für Euch: Bringt mir Wasser der Heiligen Quelle. Aber ich warne Euch: Eine Expedition von Forschern der Naga ist auf dem Weg zu der Quelle. Mit ihnen müsst Ihr Euch ebenfalls befassen.", objectives = "Scharfseher Mok'thardin von Grom'gol benötigt Wasser der Heiligen Quelle. Er will auch, dass Ihr 10 Forscher der Naga tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[574] = { title = "Spezialtruppe", description = "Nun, da viele von seinen regulären Truppen gefallen sind, müsst Ihr es mit seinen hochtrainierten Streitkräften aufnehmen. Wenn sie nicht in der Wildnis unsere Rebellensoldaten erschlagen, kann man sie tief innerhalb von Kurzens Truppenlager finden, in einer Höhle, die sie das Vorratslager nennen.\n\nIch kenne einige von Kurzens Truppen persönlich und weiß, dass sie geschickt, loyal und grausam sind. Dies ist keine einfache Aufgabe, mit der ich Euch betraue, $N.\n\nNachdem Ihr sie besiegt habt, meldet Euch bei Lieutenant Doren, meinem befehlshabenden Offizier. Er wird Euren Bericht aus erster Hand haben wollen.", objectives = "Tötet 10 von Kurzens Kommandosoldaten und 6 von Kurzens Kopfschrumpfer.\n\nErstattet Bericht bei Lieutenant Doren im Rebellenlager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[575] = { title = "Angebot und Nachfrage", description = "Der beste Ledermacher der südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.\n\nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!\n\nGerade habe ich eine Bestellung von Direktor Riddlevox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.\n\nFür die Grundform benötige ich Krokiliskenhäute von den Kroks entlang des Flusses im Norden des Schlingendorntals.", objectives = "Bringt 2 große Flusskrokiliskenhäute zu Drizzlik nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[576] = { title = "Ein Auge offen halten", description = "Haltet ein! Wer da?\n\nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezial-Glasauge verzaubert, mit dem ich wieder was sehen kann.\n\nGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Booty Bay gefunden.\n\nKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?", objectives = "Dizzy One-Eye in Booty Bay möchte, dass Ihr sein Auge von den Blutsegelbukanieren zurückholt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[577] = { title = "Etwas Zusammenbau benötigt", description = "Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir brachtet, werden leider nicht für die inneren Schichten ausreichen.\n\n\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen, und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!\n\nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokos holen, die um den Nazferitisee leben.", objectives = "Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[578] = { title = "Der Stein der Gezeiten", description = "Wenn es wirklich einen Goblinmagier und Wasserelementare gibt, die auf dieser Insel ihr Unwesen treiben, dann heißt das, dass der Stein der Gezeiten wirklich mir gehören kann!\n\nIch will, dass Ihr diese Spukinsel findet und herausfindet, wie es dort zugeht. Oh, und falls Ihr mehr über den Stein der Gezeiten herausfinden wollt, bringt diesen Schein zur Bibliothek von Stormwind, sie sollten dort ein Exemplar des Buches für Euch finden, in dem ich zuerst von der Legende gelesen habe.\n\nSollte es möglich sein, dass Gazban wirklich den Stein gefunden hat...?", objectives = "Findet die Spukinsel für Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[579] = { title = "Bibliothek von Stormwind", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[580] = { title = "Whiskey Slim's verlorener Grog", description = "Wir waren dabei, uns tüchtig einen hinter die Binde zu gießen, konnten 's Hinterland schon sehen. Dachten schon, die See wollte uns ganz und gar verschlingen.\n\nOl' Slim weiß alles über flüssigen Mut! Der Käpt'n hatte eine Kiste mit Pupellyverbos-Portwein, den wir auf'm Weg nach Stormwind von 'nem Freibeuter geholt hatten.\n\nAls der Sturm uns dann vom Hinterland aus getroffen hat, bin ich also in den Grog rein. Große Welle kam und hat die Flaschen über Bord gespült. Der Käpt'n wird mich bestimmt mit der Katze streicheln, wenn Ihr mir nich' helft, die wieder zurückzubringen!", objectives = "Whiskey Slim in Booty Bay möchte, dass Ihr ihm die Flaschen Pupellyverbos-Portwein bringt, die er verloren hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[581] = { title = "Die Suche nach Yenniku", description = "Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Darkspearstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.\n\nUnd ich glaube, dass der Bloodscalpstamm ihn hat.\n\nWenn Ihr mir helfen wollt, dann jagt die Bloodscalps. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.", objectives = "Bringt 9 Hauer der Bloodscalp zu Nimboya in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[582] = { title = "Kopfjägerei", description = "Wir müssen herausfinden, ob Yenniku tot ist.\n\nErschlagt die Kopfjäger der Bloodscalp und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.\n\nSollte Yenniku von den Bloodscalps getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!\n\nGeh, $N. Viele Kopfjäger könnt Ihr bei den Ruinen von Zuuldaia und Zul'Kunda an der Küste im Norden finden.", objectives = "Bringt 20 Schrumpfköpfe zu Nimboya in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[583] = { title = "Willkommen im Dschungel", description = "Willkommen im Schlingendorntal!\n\nIhr seid es Euch vielleicht nicht bewusst, aber der Zwerg dort drüben ist der wunderbare Hemet Nesingwary, weitbekannter Kriegsheld der Allianz und Meistergroßwildjäger. Er ist nicht gerade sehr bekannt dafür, dass er Fremde in seinem Lager sehr mag, aber Ihr seht aus, als hättet Ihr schon das eine oder andere Abenteuer erlebt, $C.\n\nDa er selbst ein erfahrener Kriegsveteran ist, hat Meister Nesingwary eine Schwäche für andere Helden.\n\nGeht und sprecht mit ihm. Vielleicht kann er Euch einige Ratschläge für die Jagd mitgeben.", objectives = "Sprecht mit Hemet Nesingwary.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[584] = { title = "Köpfe des Bloodscalpklans", description = "Yenniku war nicht unter den Köpfen, der Großen Schlange sei Dank. Aber wir sind noch weit entfernt davon, ihn zu finden.\n\nWir müssen die Wahrheit herausfinden, und ich fürchte, dass nur der Häuptling der Bloodscalp und sein Hexendoktor sie kennen. Sie sind Feinde des Darkspearstammes und werden nicht freiwillig reden, also müssen wir die Wahrheit von ihren toten Lippen erzwingen!\n\nBringt mir die Köpfe von Gan'zulah und Nezzliok dem Düsteren und legt sie in diesen Kessel.\n\nSie halten sich in den Tiefen von Zul'Kunda auf. Bringt ihre Köpfe... wir werden sie schon zum Sprechen bringen.", objectives = "Bringt Gan'zulahs Kopf und Nezzlioks Kopf zum blubbernden Kessel im Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[585] = { title = "Mit Nezzliok sprechen", description = "<Der Kopf von Nezzliok spricht.>\n\nEs stimmt. Ich weiß, wo das Kind der Darkspears hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!\n\nDie Bloodscalps streiten mit den Skullsplitters. Um mein Wohlwollen zu erhalten, stehlt 3 der Trophäenschädel von den Skullsplittern und legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah, der zweite von Ziata'jai und der dritte von Zul'Mamwe stammen.", objectives = "Bringt eine Balia'mah-Trophäe, eine Ziata'jai-Trophäe und eine Zul'Mamwe-Trophäe zum blubbernden Kessel im Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[586] = { title = "Mit Gan'zulah sprechen", description = "<Der Kopf von Gan'zulah spricht.>\n\nVerflucht seid Ihr! Und auch Eure Vorfahren!\n\nNur Blut und Rache können meine Wut beschwichtigen; wenn das Euer Wunsch ist, dann... tut Folgendes:\n\nWerft Euch in das Herz der Skullsplitter im Osten. Erschlagt die schrecklichsten unter ihnen, und wenn Ihr überleben solltet... dann tretet gegen ihren Häuptling, Ana'thek den Grausamen, an. Ha! Bringt mir seine zerschmetterte Rüstung, wenn Ihr es vermögt!\n\nMöge er Eure Glieder ausreißen und Euch der Fäulnis ausliefern und den Geiern zum Fraß vorwerfen.", objectives = "Tötet 8 Jäger der Skullsplitter, 6 Kopfjäger der Skullsplitter und 4 Berserker der Skullsplitter.\n\nBringt die zerbrochene Rüstung von Ana'thek zum blubbernden Kessel in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[587] = { title = "Auf dem Schnupftabak", description = "Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.\n\nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben , nich?\n\nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.\n\nIch wette, ein furchtloser $C wie Ihr könnte sie überreden, die Ware zu teilen, nich?", objectives = "Deeg in Booty Bay möchte, dass Ihr ihm 15 Teile Schnupftabak bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[588] = { title = "Yennikus Schicksal", description = "<Nezzliok spricht>\n\nIhr habt mich und meinen Häuptling beschwichtigt, also werde ich Euch verraten, was Ihr zu wissen wünscht...\n\nDer junge Yenniku ist für seinen Klan verloren.\n\nEr wurde von dem Hexendoktor Zanzil, dem Ausgestoßenen, verschleppt. Sein Körper und sein Geist werden jetzt durch Zanzil kontrolliert und nur eine mächtige Magie kann ihn wieder befreien.\n\nEine Magie, über die Ihr nicht verfügt, $C.\n\nMöglicherweise können Eure Verbündeten bei den Darkspear Euch etwas Hoffnung auf Yennikus Rettung bieten. Aber dies bezweifle ich.", objectives = "Sprecht mit Kin'weelay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[589] = { title = "Die singenden Kristalle", description = "Die Legenden berichten von einem Juwel, das tief im Herzen des Schlingendorntals versteckt liegt. Wir nennen es das Gedankenauge. Es verfügt über große Macht. Wenn Ihr dieses Auge finden könnt, dann können wir es vielleicht nutzen, um den verlorenen Yenniku aus der Dunkelheit zurückzubringen.\n\nIch werde mit den Geistern des Dschungels beraten, um das Gedankenauge zu finden. Während ich das tue, geht Ihr in die Kristalladermine, die sich südöstlich von hier befindet, und sammelt pulsierende blaue Splitter von den Eisenkieferbasilisken. Die Splitter gibt es nur sehr selten, aber wir benötigen ihre Magie, um das Gedankenauge unserem Willen zu unterwerfen.", objectives = "Bringt 3 pulsierende blaue Splitter zu Kin'weelay in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[590] = { title = "Ein Schurkenhandel", description = "Was?\n\nWas?!\n\nIhr wollt Geld? Ich schulde Euch kein Geld.\n\nBrief? Was für ein Brief? Oh, Ihr wollt also kämpfen? Nun, gut Kumpel... dann lasst uns anfangen! Schulde Euch Geld...", objectives = "Besiegt Calvin Montague in Deathknell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[591] = { title = "Das Gedankenauge", description = "Das Gedankenauge befindet sich bei einem Ogermagier, in den Tiefen des Ogerhügels der Mosh'Ogg östlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Darkspears im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.\n\nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.\n\nIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.", objectives = "Bringt das Gedankenauge zu Kin'weelay in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[592] = { title = "Yennikus Rettung", description = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.\n\nDann bringt Ihr den Edelstein zu Nimboya.\n\nYenniku ist bei Zanzil dem Ausgestoßenen, in den Ruinen von Aboraz, entlang des Kristallufers am fernen Kap des Schlingendorntals.", objectives = "Bringt den gefüllten Seelenedelstein zu Nimboya.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[593] = { title = "Den Seelenedelstein füllen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[594] = { title = "Flaschenpost", description = "In der Notiz steht Folgendes in recht guter Handschrift:\n\nAn alle, die mir helfen können:\n\nBitte, ich benötige dringend Hilfe. Ein großer Blaumähnengorilla hält mich auf einer Insel in den südlichen Meeren gefangen.\n\nDie Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die wilden Ufer im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.\n\nIch flehe Euch an, mein möglicher Retter, bitte helft mir.", objectives = "Findet den Schreiber dieser Flaschenpost.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[595] = { title = "Die Blutsegelbukaniere", description = "Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, $R, und ein $C noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.\n\nUnser Schiff hat gerade hier in Booty Bay angedockt und es heißt, dass unsere Rivalen - diese verdammten, dreckigen Blutsegelbukaniere - sich im gesamten Süden des Schlingendorntals herumtreiben.\n\nMeine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.\n\nBegebt Euch zur Bucht im Norden von Booty Bay an der ungezähmten Küste und schaut, was Ihr so findet.", objectives = "Erster Maat Crazz will, dass Ihr die Bucht nördlich von Booty Bay überprüft.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[596] = { title = "Blutige Knochenhalskette", description = "Ich wurde nach Grom'gol geschickt, um Nimboya auf seiner Suche zu begleiten, aber... Ich habe meine eigenen Gründe, hier zu sein.\n\nDer Bloodscalpstamm ist der Feind unseres Stammes. Wenn wir Trophäen unserer Feinde sammeln, erhalten wir Macht über sie. Ihr könnt unserem Stamm behilflich sein, indem Ihr unsere Feinde jagt.\n\nSie leben im Norden. Erschlagt die Trolle der Bloodscalp und nehmt ihre blutigen Knochenhalsketten mit. Wenn Ihr viele davon sammelt, wird Eure Belohnung groß sein.", objectives = "Bringt 25 blutige Knochenhalsketten zu Kin'weelay in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[597] = { title = "Die Blutsegelbukaniere", description = "Die Karte zeigt Booty Bay mit einem roten \"X\" genau an dem Punkt, wo Ihr gerade steht.\n\nDer hingekritzelte Text lautet:\n\n\"Leute, errichtet ein Lager an dieser Stelle und verhaltet euch schön unauffällig. Wartet auf das Signal vom südlichen Kommandoposten, bevor ihr angreift. Wenn sich jemand euch nähert, tötet ihr ihn.\"", objectives = "Berichtet dem ersten Maat Crazz in Booty Bay von Euren Funden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[598] = { title = "Spaltknochenhalskette", description = "Nun, da Ihr Bloodskalp-Trophäen gesammelt habt, habe ich eine weitere Aufgabe für Euch. Der Skullsplitterstamm der Trolle lebt im Südwesten und wir bekämpfen sie schon seit Jahren. Obwohl keine Darkspears mehr im Schlingendorntal leben, sind wir immer noch dem Konflikt mit den Skullsplittern verpflichtet.\n\nAlso, jagt sie. Sammelt ihre Spaltknochenhalsketten und kehrt zu mir zurück. Helft uns in unserem Krieg und Ihr werdet die Freundschaft der Darkspears erlangen.", objectives = "Bringt 25 Spaltknochenhalsketten zu Kin'weelay in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[599] = { title = "Die Blutsegelbukaniere", description = "Neee, isses denn wahr! Also planen die Blutsegelbukaniere einen Angriff auf Booty Bay? Diese Schurken haben vielleicht Nerven. Booty Bay wird immer von den Schwarzmeerräubern beherrscht werden!\n\nDas ist ein größeres Unterfangen als ich dachte. Erstattet Flottenmeister Seehorn sofort Bericht über alles, was Ihr erfahren habt! Der alte Seebär ist irgendwo in der Stadt...", objectives = "Erstattet Flottenmeister Seehorn Bericht über den geplanten Angriff der Blutsegelbukaniere.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[600] = { title = "Venture Company-Bergbau", description = "Die Venture Company hat ein paar Sachen im Schlingendorntal am Laufen, die hart arbeitende Goblins, wie ich es einer bin, davon abhalten, ehrliches Gold zu verdienen. Bitte, Ihr müsst mir helfen!\n\nDie Venture Company betreibt einen Stollen in der Nähe der Kristalladermine im Norden. Sie kommen nicht in die Mine hinein wegen der ganzen Basilisken, aber trotzdem sind sie in der Lage, singende Kristalle aus den umgebenden Hügeln herauszugraben.\n\nNehmt ihnen die Kristalle ab und zeigt ihnen, dass sie im Dschungel nichts zu melden haben.\n\nUnd... ähm... bringt mir diese Kristalle als Beweis!", objectives = "Bringt 10 singende blaue Kristalle zu Crank Fizzlebub nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[601] = { title = "Wasserelementare", description = "Die Wasserelementare wurden ohne Zweifel von Gazban, dem Goblinhexer beschworen, von dem man behauptet, er habe den Stein der Gezeiten entdeckt. Wie Ihr vielleicht wisst, verflucht der Stein der Gezeiten seinen Träger, sodass er ständig zwischen Sein und Nicht-Sein wandelt.\n\nVielleicht können wir einen Weg finden, dem Fluch entgegenzuwirken. Ein Magier von Dalaran kann die magischen Überreste einer der Armschienen des Wasserelementars für uns analysieren. Ihr müsst wieder zurück zur Insel und einige Exemplare davon herbringen.", objectives = "Holt 6 Wasserelementararmschienen für Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[602] = { title = "Magische Analyse", description = "Wie ich gehört habe, sind die Magier von Dalaran sehr damit beschäftigt, ihre zerstörte Stadt wieder aufzubauen. Ich bin aber trotzdem sicher, dass Ihr einen finden könnt, der sich etwas Zeit für diese Armschienen nehmen wird. Denn wenn ich etwas über Magier weiß, dann, dass sie einem magischen Rätsel einfach nicht widerstehen können.\n\nNehmt diese Tasche mit Wasserelementararmschienen und findet heraus, ob sie in irgendeinem Zusammenhang mit dem Fluch des Steins stehen. Sucht vor allem nach dem Erzmagier Ansirem Runeweaver. Ich hatte schon zuvor mit ihm zu tun und er verfügt über unglaubliches Wissen.", objectives = "Bringt die Wasserelementararmschienen nach Dalaran zu Erzmagier Ansirem Runeweaver.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[603] = { title = "Ansirems Schlüssel", description = "Der Magier, der im Besitz dieses Steins ist, verstärkt seine Macht durch ein Zentrum... eine Art Altar. Ihr solltet in der Lage sein, dies zu unterbrechen, indem Ihr es überwältigt.\n\nWie es der Zufall will, weiß ich auch genau womit: ein alter Dolch, ein weiteres Trollrelikt. Es gibt da nur ein... winzigkleines Problem.\n\nWisst Ihr, ich fand den Dolch auf einer Forschungsreise im Schlingendorntal, aber ich gab ihn meiner eigenwilligen Tochter, Catelyn, die mir nach Booty Bay weglief, um Piratin zu werden.", objectives = "Sprecht mit Catelyn in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[604] = { title = "Die Blutsegelbukaniere", description = "Crazz lobt Eure Hingabe an die Schwarzmeerräuber in hohen Tönen. Ich werde Euch mit einer Mission betrauen, die für die Flotte von höchster Bedeutsamkeit ist.\n\nBespitzelt den so genannten südlichen Kommandoposten, den die Blutsegelbukaniere an den wilden Ufern aufgebaut haben. Überfallt das Lager. Bringt mir ihre Karten zusammen mit ihren schriftlichen Befehlen. Wir werden ganz genau herausfinden, was dieser Abschaum so vorhat.", objectives = "Flottenmeister Seehorn in Booty Bay will, dass Ihr 10 Schwadroneure der Blutsegelbukaniere tötet und die Blutsegelkarten sowie die Blutsegelbefehle zurückbringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[605] = { title = "Singende blaue Splitter", description = "Die singenden Kristalle gibt es nur im Schlingendorntal und sie sind für gewisse Gruppierungen äußerst wertvoll. Ich kann diese Kristalle bewegen, aber die verfluchte Venture Company macht es einem ehrlichen Unternehmer wie mir fast unmöglich, überhaupt welche zu sammeln.\n\nIch würde Euch gern anheuern.\n\nDie Basilisken des Schlingendorntals essen die Kristalle. Dadurch erhalten sie ihre harte Haut und manchmal können Kristalle von ordentlicher Qualität von den Häuten abgesammelt werden.\n\nIhr könnt sie von jedem Basilisken sammeln, aber die nicht ganz so bösartigen leben an der Küste südlich von Zul'Kunda, im Norden.", objectives = "Bringt 10 singende Kristallsplitter zu Crank Fizzlebub.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[606] = { title = "Zitterhand Angst einjagen", description = "Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?\n\nDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.\n\nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.", objectives = "Bringt 5 Nebeltalinnereien zu \"Zitterhand\" Phillipe nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[607] = { title = "Rückkehr zu MacKinley", description = "Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich ihm alles zurückzahlen wollte! Ich schwöre!!\n\nIch hab nur ein bisschen viel getrunken und mich verlaufen, und... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!", objectives = "Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[608] = { title = "Die Blutsegelbukaniere", description = "Dieser verdammte Firallon! Könnte kein Boot in einem Stück über den Kristallsee bringen, ganz zu schweigen eine ganze Flotte gegen uns führen.\n\nDie Blutsegelbukaniere werden für ihre Sorglosigkeit teuer bezahlen. Jetzt, da wir ihren Angriffsplan kennen, können wir unseren Gegenschlag starten, bevor sie überhaupt merken, was los ist.\n\nAber warum sollten wir die ganze Flotte schicken, wenn eine mutige Gruppe von Abenteurern das auch allein schaffen kann? $n, nehmt einige von Euren geschicktesten Kameraden zu Firallons Ankerplatz und tötet die Führungskräfte der Blutsegelbukaniere. Ihre Flotte wird bald danach sinken ...", objectives = "Flottenmeister Seehorn in Booty Bay will, dass Ihr Kapitän Stillwasser, Käpt'n Kielhol und Flottenmeister Firallon tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[609] = { title = "Voodooschulden", description = "Meine Liste wird kürzer, aber da sind immer noch Leute, die mir was schulden.\n\nAls Nächste haben wir da Maury \"Klumpfuß\" Wilkins, Jon-Jon die Krähe und Chucky \"Zehn Daumen\".\n\nDie Schulden dieser räudigen Hunde stehen schon seit Monaten aus und ich dachte schon, dass sie die Stadt verlassen hätten, nur um nicht zahlen zu müssen! Später hab ich gehört, dass sie jetzt verflucht und verhext sind und in den Dschungelruinen ihr Unwesen treiben. Aber ihr Schicksal ist mir ziemlich egal - ich will nur, was mir zusteht!\n\nSie halten sich in den Ruinen von Aboraz und den Ruinen von Jubuwal nordöstlich von hier auf. Sucht sie und holt das Geld.", objectives = "Bringt Maurys Klumpfuß, Jon-Jons goldenes Handfernrohr und Chuckys gewaltigen Ring zu \"Seewolf\" MacKinley in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[610] = { title = "Schönling Duncan", description = "Mein VATER hat Euch geschickt? Dachte, der alte Knacker hätte mich mittlerweile aufgegeben.\n\nEs war ja nicht unbedingt sein Fehler, dass ich weggerannt bin, er hätte einfach nicht erwarten dürfen, dass ich Lust auf ein langweiliges Leben hab, alte muffige Bücher lese und mich mit grauhaarigen, steifen, hochnäsigen Magiern abgebe!\n\nWenn Ihr meinen Dolch braucht, müsst Ihr ihn von \"Schönling\" Duncan wiederholen, einem der Blutsegelbukaniere. Rammt einfach was zwischen seine Schultern und er wird ihn sicherlich sofort rausrücken.", objectives = "Holt Catelyns Dolch von \"Schönling\" Duncan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[611] = { title = "Der Fluch der Gezeiten", description = "Ihr sucht also nach einer Art Altar? Nun, ich bin zwar kein Experte für Trollruinen wie mein Vater, aber ich habe von einer versunkenen Trollstadt nah bei der Insel gehört, die Ihr sucht. Vielleicht solltet Ihr dort mal suchen.\n\nIhr habt mein Messer für mich wiedergeholt, also könnt Ihr es Euch auch borgen... Ich will es aber wiederhaben, wenn Ihr fertig seid!", objectives = "Zerstört den Altar der Gezeiten mit Catelyns Klinge, tötet Gazban und bringt dann den Stein der Gezeiten sowie Catelyns Klinge zurück zu Baron Revilgaz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[613] = { title = "Maurys Fuß aufbrechen", description = "Verflucht noch eins! Dieser Blödmann Maury hat ein Schloss an seinem Fuß befestigt und ich kann es nicht öffnen! Seine Beute ist in dem Fuß, und das sind seine Schulden!\n\nWir müssen den Schlüssel finden, dann kriegen wir auch das Schloss auf. Maury hat mit den Ogern der Mosh'Ogg gespielt, in ihrem Hügel im Nordosten. Als er noch lebte, erzählte er mir, dass sie ihn das letzte Mal von dort verjagt hätten, weil er zu viel gewonnen habe. Vielleicht haben die Oger ja seinen Schlüssel.\n\nWenn sie ihn haben sollten, müsstet Ihr eine ganze Menge von ihnen beseitigen, bevor Ihr den richtigen findet.", objectives = "Bringt Maurys Schlüssel zu \"Seewolf\" MacKinley in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[614] = { title = "Die Truhe des Kapitäns", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratchet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Booty Bay gesteckt. Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Er sagte, er wolle sie als Schnupftabakdose. Diese Dreistigkeit!\n\nIch habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", objectives = "Bringt Smotts' Truhe zu Hecklebury Smotts nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[615] = { title = "Der Entersäbel des Kapitäns", description = "Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.\n\nDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.\n\nStellt Euch Negolash und bringt mir meinen Entersäbel!\n\nSprecht mit Knirpsens. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.", objectives = "Sprecht mit Knirpsens.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[616] = { title = "Die Spukinsel", description = "Für Baron Revilgaz höre ich mich immer nach Gerüchten von seltsamen und ungewöhnlichen Dingen in Booty Bay und im Schlingendorntal um. Normalerweise gebe ich ja nicht viel auf Geistergeschichten, aber ich habe ein paar Seeleute in der Taverne über eine Insel nahe der Küste reden hören, auf der es spuken soll. Sie erzählten von Wasserelementaren und einem rasenden Goblingeist.\n\nWenn Ihr mit Revilgaz sprechen solltet, erzählt Ihr ihm davon?", objectives = "Sprecht mit Baron Revilgaz in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[617] = { title = "Bündelweise Akiris", description = "Sucht'er Arbeit, $n? Hab vielleicht was für Euch, wenn'er Euch was traut.\n\nMein Freund Groy verdient sich dumm un' dämlich mit dem Verkauf von dem Zeuch, das die Naga Akirisschilfrohr nennen: is' so 'ne Art wertvolles Meeresschilfrohr. Bin nich' sicher, für was es gut is', aber er bezahlt gut für Bündel von dem Zeuch.\n\nWenn Ihr mir 10 Stängel von dem Zeuch bringt, sind wa im Geschäft. Die Naga wurden zuletzt am Strand nördlich von hier gesehen.", objectives = "Bringt 10 Stängel Akirisschilfrohr zu Freibeuter Bloads nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[618] = { title = "Negolash entgegentreten", description = "Negolash ist ein hungriger Riese.\n\nAls die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen. Negolash wollte Wein... und meine gegrillten Bussardflügel. Die sind meine Spezialität. Für das Rezept musste ich bis ins Ödland reisen!\n\nWenn Ihr den Riesen anlocken wollt, dann besorgt Euch etwas Wein und einen Haufen Bussardflügel. Legt sie in unser altes Rettungsboot, an der Küste südöstlich von hier. Sobald Negolash das Essen riecht, wird er bestimmt kommen!", objectives = "Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.\n\nTötet Negolash und bringt Smotts' Entersäbel zu Captain Smotts ins Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[619] = { title = "Negolash anlocken", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[621] = { title = "Zanzils Geheimnis", description = "Zanzil der Ausgestoßene hält sich mit seinen Anhängern in den Ruinen von Aboraz und Jubuwai auf, nordöstlich von Booty Bay. Sein Stamm hat ihn verbannt. Warum? Nun...\n\nZanzil hat eine Methode, den Geist von anderen zu beugen, und seine Anführer fürchten ihn. Er benutzt eine Mixtur von Dschungelpflanzen, die den Willen seiner Anhänger unterdrücken und ihre Körper stärken.\n\nSeine Mixtur könnte sehr wertvoll für diejenigen sein, die andere zu kontrollieren wünschen.\n\nBringt mir Proben seiner Mixtur und ich werde einen Nutzen für sie finden.", objectives = "Bringt 12 Proben von Zanzils Mixtur zu Crank Fizzlebub nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[622] = { title = "Rückkehr zu Corporal Kaleb", description = "Während Ihr fort wart, habe ich den Topf, den Ihr mir brachtet, repariert. Ich habe sogar noch eine zusätzlich Dampfpfeife angebracht, und seht mal! Da ist ein neues Hackbeil am Boden, das kann Beinknochen durchtrennen.\n\nJa, ja, Krazeks Spezialtopf weiß, was Köche wünschen! Sein Besitzer wird bestimmt erfreut sein.", objectives = "Bringt Krazeks reparierten Topf zu Corporal Kaleb im Rebellenlager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[623] = { title = "Bündelweise Akiris", description = "Ach ja, $N, fein dass Ihr hier seid. Während Eurer Abwesenheit hab ich 'ne Nachricht von Groy gekricht. Er sachte, dass er mit der letzt'n Lieferung sehr zufrieden war und dass 'n Kunde von ihm noch mehr von dem Zeuch hab'n will und das sofort.\n\nIch fahr erst inner Woche wieder nach Theramore, aber wenner den Weg nich' scheut, dann könnter auch gleich das Zeuch für mich mitnehmen.\n\nAbenteuerlustich? Wissen tut er ja, wo die Marschen von Dustwallow sin', nich'? Ich wär aber vorsichtich, Theramore kann gefährlich sein, wenn man inne falschen Kreise kommt.", objectives = "Bringt ein Bündel Akirisschilfrohr zu Freibeuter Groy nach Theramore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[624] = { title = "Cortellos Rätsel", description = "Eine Brücke verziert und stark frequentiert\nUnter ihr werdet Ihr finden was Euch sehnlichst erwartet\nManche nennen es Hinweis andere Tipp\nEs liegt östlich der Schlucht der Totenwinde und südlich vom Rotkammgebirge\nFür unendliche Zeit genau dort wird es liegen\nIn den Sümpfen des Elends sich für immer wiegen\n", objectives = "Löst das Rätsel!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[625] = { title = "Cortellos Rätsel", description = "Im fernen Kalimdor wartet ein Land\nDie Hoffnung hielt dort den Gefahren nicht stand\nDas Wetter östlich des Brachlandes ist harsch\nDunkel und Tod droh'n in der Dustwallowmarsch\nDoch in einer Höhle, Richtung Südwest\nLiegt ein Hinweis für alle, die wagen den Test.", objectives = "Löst das Rätsel!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[626] = { title = "Cortellos Rätsel", description = "Nach Lordaeron! Schwerer Aufruhr dort wütet\nSoldatenmut wird mit dem Tode vergütet\nSucht Euren Weg durch den Aufstand dort\nund Eure Such' ist beendet an einem Ort\nAm Fuße der großen Fälle, entlang der Küste im Hinterland\nIm Wasser dort tief unten, nehmt Ihr Euren Schatz in die Hand!", objectives = "Löst das Rätsel!", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[627] = { title = "Gefallen für Krazek", description = "Es gibt eine Berghöhle in der Schlucht der Trockenstoppel, weit im Norden des Arathihochlands. In dieser Höhle findet sich ein seltenes Erz: Blutstein. Der Blutstein in dieser Höhle ist zwar nicht von höchster Qualität, aber auch Blutstein von minderer Qualität ist wertvoll... für diejenigen, die wissen, wie er zu nutzen ist.\n\nIch hätte gerne etwas davon.\n\nIch werde Euren Spezialtopf reparieren, aber während ich daran arbeite, möchte ich, dass Ihr mir einige Blutsteinproben bringt. Bringt mir genügend und Ihr erhaltet einen Bonus.\n\nOh, und falls Ihr nicht wisst, wie man ihn abbaut... findet jemanden, der es kann!", objectives = "Bringt 4 Ladungen geringes Blutsteinerz zu Krazek nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[628] = { title = "Exzelsior", description = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.\n\nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Die Alten kommen nur heraus, um die anderen Salzwasserkroks zu verteidigen, also werdet Ihr wahrscheinlich einige töten müssen, um einen von der Sorte herauszulocken.", objectives = "Bringt die Haut eines alten Krokilisken zu Drizzlik nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[629] = { title = "Das Finstere Riff", description = "Vor langer Zeit, als ein großes Beben die Welt erschütterte, versank eine alte Trollstadt in den Wassern der ungezähmten Küste im Nordwesten. Wir nennen diesen Ort das finstere Riff, denn Murlocs bewohnen jetzt die Ruinen der Stadt und greifen jeden an, der sich ihnen nähert.\n\nIn diesen alten Ruinen liegt eine alte Schrifttafel, die die uralte Geschichte von Gri'lek erzählt, einem Helden der Trolllegenden. Diese Geschichte ist dem Darkspearstamm heilig und auch wenn die Tafel zu groß ist, um sie zu bewegen, so möchte ich doch einen Splitter davon, damit ich ihn in unserer neuen Heimat in Orgrimmar in einen Schrein legen kann.", objectives = "Bringt 1 Schrifttafel-Splitter zu Kin'weelay in das Basislager von Grom'gol.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[630] = { title = "Flaschenpost", description = "$N, ich setze meine ganze Hoffnung in Euch und jeden, den Ihr gewinnen könnt, um mich zu befreien. Der große Blaumähnenkönig Mukla hat mich gefangen genommen. Er befehligt die Bestien dieser Insel und sie halten mich mit Hilfe dieser Kette gegen meinen Willen hier fest. Wenn Ihr ihn töten und den Schlüssel für diese Fessel finden könnt, stehe ich tief in Eurer Schuld.\n\nIch habe ihn oft auf der südöstlichen Seite der Insel gehört, aber bitte seid vorsichtig: Man darf ihn nicht unterschätzen.", objectives = "Erschlagt König Mukla und kehrt mit dem Schlüssel zu Prinzessin Poobah zurück, um sie zu befreien.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[631] = { title = "Der Thandol-Übergang", description = "Eine enorme Explosion donnerte durch die Hügel hinweg. 's war furchtbar, sag ich Euch!\n\nGute Soldaten starben bei der Verteidigung des Thandol-Übergangs. Longbraid sagt, wir werden uns noch an den Dunkeleisenzwergen rächen.\n\nAber wir befinden uns in einer Welt voller Schmerz, und Verstärkung ist noch lange nicht in Sicht. Longbraid hat Ol' Rustlocke als Späher zur östlichen Brücke geschickt, um rauszufinden, ob wir sie sichern können.\n\nDas ist aber schon Tage her. Und jetzt, wo Dun Modr belagert wird, haben wir nicht genug Leute, um nach ihm zu suchen.\n\nVielleicht könnt Ihr ihn finden...", objectives = "Rhag Garmason will, dass Ihr Ol' Rustlocke findet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[632] = { title = "Der Thandol-Übergang", description = "Es sieht ganz so aus, als sei der arme Ol' Rustlocke in einen Hinterhalt der Dunkeleisenzwerge geraten. Ihr bemerkt ein Pergament neben seinen geballten Fäusten.\n\nErstattet Rhag Garmason Eure traurigen Neuigkeiten und zeigt ihm, was Ihr gefunden habt.", objectives = "Meldet Euch bei Rhag Garmason zurück und zeigt ihm das Pergament, das Ihr bei Rustlockes Leichnam gefunden habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[633] = { title = "Der Thandol-Übergang", description = "Um Himmelswillen, nein! Armer Rustlocke. Das ist wirklich eine fürchterliche Tragödie.\n\nSein Tod darf nicht vergebens sein. Das Pergament, das Ihr entdeckt habt, zeigt an, dass Kam Deepfury, der hinter dem eigentlichen Angriff steckt, dafür gesorgt hat, dass ein Behälter mit Sprengstoff hinter dem Thandol-Übergang im Arathihochland versteckt wurde.\n\nWenn dieser Sprengstoff  zur Brücke gelangt, wird unsere Hauptversorgungsverbindung in den Norden gekapp! Der Behälter muss zerstört werden, $n! Kehrt zu mir zurück, wenn Ihr Eure Mission erfüllt habt.\n\nIhr seid unsere einzige Hoffnung.", objectives = "Zerstört den Sprengstoffbehälter", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[634] = { title = "Hilfegesuch an die Allianz", description = "Ich bitte Euch noch um einen kleinen Gefallen, $C. Wir erwarten die Reserven von Ironforge. Roggo hat jedoch von einem Lager der Allianz im Norden des Arathihochlands bei der Zuflucht erfahren.\n\nReist dorthin und macht Captain Nials ausfindig. Fragt den guten Captain, ob die Allianz einige Soldaten erübrigen kann, die uns behilflich sein können, Dun Modr und den Thandol-Übergang zurückzuerobern.", objectives = "Macht Captain Nials bei der Zuflucht ausfindig.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[635] = { title = "Kristall in den Bergen", description = "Dieser Splitter pulsiert während Ihr ihn haltet...\n\nIhr habt das Gefühl, als ob ein Bitten vom Splitter ausgeht, als ob jemand versucht, mit Euch zu kommunizieren, jemand, der verzweifelt Eure Hilfe sucht.\n\nVor Eurem inneren Auge erscheint eine Vision - die nördlichen Berge von Arathi und ein blitzender Kristall, der dort aus dem Boden ragt.\n\nIhr spürt, wie es Euch dorthin zieht.", objectives = "Findet den Kristall aus Eurer Vision.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[636] = { title = "Legenden der Erde", description = "Dieses Buch erzählt die Geschichte einer Prinzessin der Elementare, Myzrael, und ihrer Gefangenschaft tief unterhalb des Arathihochlandes.\n\nEs erzählt auch von dem verborgenen Auftreten von Kristallen im Hochland. Diese Kristalle, die Splitter von Myzrael, sind Fenster zum Gefängnis der Prinzessin.\n\nWenn eine mutige Seele die Splitter von Myzrael fände, dann könnte $Ger:sie; vielleicht mit ihr sprechen...", objectives = "Findet die Splitter von Myzrael.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[637] = { title = "Sully Balloos Brief", description = "Der durchnässte und zerrissene Umschlag löst sich in Euren Händen auf und Euch bleiben nur einige Seiten eines Briefes, der mit viel Mühe geschrieben wurde.\n\nDer Brief ist adressiert an eine Mrs. Sara Balloo in Ironforge und beginnt mit den Worten, \"Meine liebe Sara ...\".", objectives = "Bringt Sully Balloos Brief zu Sara Balloo.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[638] = { title = "Trollbann", description = "Da Thoras Trollbane tot ist und Stromgarde in Schutt und Asche liegt, hat Vol'jin Anweisungen gegeben, dass wir alles tun sollen, um das legendäre Schwert Trol'kalar den menschlichen Händen zu entreißen, auf dass wir es in zukünftigen Kämpfen gegen die Trolle von Zul'Gurub nutzen können.\n\nZengu, einer unserer erfahrenen Jäger, wurde nach Hammerfall im Nordosten des Arathihochlands entsandt, um seine Beschaffung zu leiten.", objectives = "Reist nach Hammerfall im Arathihochland und sprecht mit Zengu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[639] = { title = "Siegelzeichen von Strom", description = "In den alten Zeiten kämpften Trolle gegen das Arathorianische Reich und unseren geschicktesten Feind, Lord Ignaeus von Strom, genannt Trollbane. Er ritt in die Schlacht und schwenkte dabei sein Schwert Trol'kalar - was in ihrer alten Sprache Trolltöter heißt.\n\nAber jetzt sind die Söhne von Trollbane geschwächt, ihre Festung ist dem Verfall preisgegeben.\n\nDas Schwert wird von mehreren Siegelzeichen beschützt, die unter den Überlebenden von Stromgarde verteilt wurden. Wir müssen sie alle bekommen.\n\nDas Erste wurde von dem Syndikat mitgenommen, einer ihrer Männer in Stromgarde sollte es haben.", objectives = "Holt das Siegelzeichen von Strom für Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[640] = { title = "Das zerbrochene Siegelzeichen", description = "Thoras Trollbanes Grabmal wird durch drei Siegelzeichen beschützt - das Erste davon habt Ihr dem Syndikat entwendet. Es wird allerdings schwieriger sein, an die anderen beiden heranzukommen, da sie sich bei der Miliz von Stromgarde befinden und diese sich gut verschanzt hat.\n\nDas Siegelzeichen von Thoradin wurde von Thoras' Sohn, Galen, in 11 Teile aufgeteilt und unter den Verteidigern von Stromgarde verteilt. Holt die Stücke und bringt sie zu Tor'gan, dem Trollschamanen, er kann sie wieder zum vollständigen Siegelzeichen binden.", objectives = "Holt die 11 Siegelzeichen-Fragmente von den Verteidigern in Stromgarde und bringt sie zu Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[641] = { title = "Siegelzeichen des Thoradin", description = "Die Rekonstruktion ließ sich problemlos durchführen. Das Siegelzeichen kann nun benutzt werden, um das Siegel auf Trollbanes Grabmal aufzuschließen. Bringt es zu Zengu, er hat ohne Zweifel weitere Aufgaben, die Ihr erfüllen müsst.", objectives = "Bringt das wiederhergestellte Siegelzeichen von Thoradin zu Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[642] = { title = "Die gefangene Prinzessin", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, $n, helft mir!", objectives = "Sammelt 12 Körner von Myzrael und bringt sie zu den regenbogenfarbenen Splittern in der Schlucht der Trockenstoppel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[643] = { title = "Siegelzeichen von Arathor", description = "Obwohl man kaum behaupten kann, dass sie Stromgarde kontrollieren, geschweige denn das gesamte Arathihochland, marschiert der menschliche Prinz trotzdem mit den Überbleibseln seiner Kavallerie durch das Land. Ich versteh ja nicht, warum er das tut, aber wer versteht schon, wie Menschen ticken, hm?\n\nWas auch immer seine Gründe sein mögen, er hat eines der Siegelzeichen Lieutenant Heldenruf, dem Anführer seiner Kavallerie übergeben. Findet ihn und bringt mir sein Siegelzeichen zurück.", objectives = "Holt das Siegelzeichen von Arathor und bringt es Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[644] = { title = "Siegelzeichen von Trollbane", description = "Das letzte Siegelzeichen, das benötigt wird, um das Siegel auf dem Grabmal von Thoras Trollbane zu öffnen, wird von seinem Sohn höchstpersönlich aufbewahrt. Er hält sich tief innerhalb Stromgardes auf, in einer Kapelle in den von der Miliz bewachten Distrikten. Prinz Galen wird gut bewacht und da er selbst ein ausgezeichneter Krieger ist, wird diese Aufgabe wahrscheinlich die schwierigste sein.", objectives = "Tötet Prinz Galen Trollbane und bringt das Siegelzeichen von Trollbane zu Zengu in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[645] = { title = "Trol'kalar", description = "Was ist das? Die vier Siegelzeichen haben sich zu einem Siegelzeichen zusammengefügt. Ohne Zweifel ist dieses in der Lage, die Schutzzeichen zu zerbrechen, die sich auf Trollbanes Grabmal befinden.\n\nTrollbanes sterbliche Überreste sind im Sanktum hinter der Kapelle in Stromgarde zur Ruhe gebettet worden. Holt Trol'kalar.", objectives = "Holt Trol'kalar aus Trollbanes Grabmal in Stromgarde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[646] = { title = "Trol'kalar", description = "Das Licht verglüht langsam, das Schwert Trol'kalar, das sich in einer steinernen Scheide befindet, ist freigegeben.", objectives = "Bringt Trol'kalar zu Zengu nach Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[647] = { title = "MacKreels Fusel", description = "Was hab ich gestern gesoffen! Longbraid würde mich sofort köpfen, wenn er wüsste, dass ich während meiner Wache eingepennt bin.\n\nMein Schädel brummt vielleicht. Fühlt sich an, als wäre eine ganze Brigade von Belagerungsmaschinen drübergerollt, dieses Gerumpel.\n\nOh weh, so spät schon! Hab Braumeister Bilger in Southshore versprochen, dass ich meine Schulden mit ein wenig Fusel bei ihm bezahlen würde.\n\nUnd ich hab nur noch 15 Minuten! Könntet Ihr ihm diese Lieferung nicht bringen, bitte? Und beeilt Euch!", objectives = "Bringt MacKreels Fusel zu Braumeister Bilger nach Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[648] = { title = "Rettet OOX-17/TN!", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-17/TN an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Ihr müsst den Roboter von seinem derzeitigen Standort nach, sagen wir, Steamwheedle bringen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn sicher bis zum Hafen und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"", objectives = "Eskortiert OOX-17/TN nach Steamwheedle und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[649] = { title = "Bergung der Welle", description = "Ich habe eine kleine Bergungsaktion für Euch, und falls Ihr ein Liebhaber von feiner Welle seid, so wie ich, dann werdet Ihr diese Aufgabe lieben. Welle!\n\nDas ist ein Getränk, Schafskopf.\n\nEin verlassener Außenposten der Horde verfügt über ein Lager mit Hinterland-Honigwelle aus der Zeit, als sie noch im Geschäft waren. Solch feine Welle bekommt Ihr sonst nirgendwo! Einer von Maltons Strohmännern weiß Bescheid, also begebt Ihr Euch dorthin und bringt mir eine Kiste verpackter Welle und zwei für meine eigene Sammlung! Sprecht mit Malton, er wird Euch die Einzelheiten mitteilen.", objectives = "Sprecht mit Malton Droffers in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[650] = { title = "Bergung der Welle", description = "Der Elf, mit dem Ihr sprechen müsst, ist Gilveradin Sunchaser. Er erkennt jeden Wein, mit Jahrgang und allem, allein am Geruch! Er kann die Welle verpacken, die wir benötigen, daher müsst Ihr mit ihm sprechen. Sechs Flaschen müssen verpackt werden, zwei für meinen Vater, und so viele wie er selbst will... und glaubt mir, er wird welche wollen. Wenn Ihr die Welle verpackt habt und auch die zwei Flaschen für meinen Vater, dann kommt hierher zurück!\n\nGilveradins Lager befindet sich in der Nähe einer Hochelf-Lodge im Hinterland, und diese Hochelfen führen nichts Gutes im Schilde. Glaubt mir.", objectives = "Sprecht mit Gilveradin Sunchaser; sein Lager befindet sich im Hinterland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[651] = { title = "Steine der Bindung", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der Inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", objectives = "Holt den brennenden Schlüssel, den Wappenschlüssel und den donnernden Schlüssel vom Stein der westlichen Bindung, dem Stein der östlichen Bindung und dem Stein der äußeren Bindung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[652] = { title = "Den Hauptstein zerbrechen", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n$n, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", objectives = "Findet und tötet Fozruk. Bringt die Rute der Ordnung zum Hauptstein im Arathihochland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[653] = { title = "Myzraels Verbündete", description = "<Myzrael spricht.>\n\nFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einkerkern.\n\nAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangenen gehalten zu haben!\n\nIhr seid ein edelmütiger Verbündeter, $N. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, müsst Ihr mich an die Oberfläche beschwören.\n\nSprecht mit Gerrig Bonegrip. Er befindet sich in Ironforge in einem Geschäft im düsteren Viertel. Er weiß, wie ich beschworen werden kann.", objectives = "Sprecht mit Gerrig Bonegrip im düsteren Viertel von Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[654] = { title = "Tanaris-Feldproben", description = "Nach Aktivierung der Kraftquelle beginnt das Feldtestset zu glühen und zu vibrieren. Es scheint, als würde es funktionieren wie geplant.\n\nLaut Chefingenieur Bilgewhizzle habt Ihr zwei Stunden Zeit, um die benötigten Daten in der Tanariswüste zu sammeln. Falls Ihr sie nicht innerhalb von zwei Stunden sammelt, gehen alle Daten verloren und Ihr müsst eine weitere Kraftquelle von ihm erstehen.\n\nKehrt zu ihm zurück, wenn Ihr Eure Aufgabe erfüllt habt.", objectives = "Sammelt akzeptable Proben von 8 Basilisken, 8 Hyänen und 8 Skorpionen. Bringt das Testset zurück nach Gadgetzan zu Chefingenieur Bilgewhizzle, bevor die Kraftquelle erschöpft ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[655] = { title = "Hammerfall", description = "Ich erinnere mich, als wär es gestern gewesen... So viele Jahre ohne Hoffnung, mit Holz und Stahl, die mich an diesen fürchterlichen Ort banden. Und dann endlich, endlich! Da war der Kriegshäuptling. Doomhammer in seiner Mitternachtsrüstung, sein Kriegshammer hoch erhoben.\n\nEs war... zu schrecklich... Dass der Schlag eines Feiglings unseren größten Helden niederschlagen konnte. Er kam von hinten angestürmt auf seinem Pferd und dann rammte er seine Lanze einfach durch ihn hindurch... Ich fiel auf die Knie. Welche Hoffnung gab es noch? Welche Hoffnung gibt es noch...", objectives = "Sprecht mit Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[656] = { title = "Beschwören der Prinzessin", description = "Ihr müsst Myzrael besiegen, bevor ihre Kraft größer wird. Wenn Ihr es nicht tut, wird sie ihre Häscher herausfordern, sobald sie genug Stärke gesammelt hat! Einige glauben zwar, dass man sie kontrollieren könnte, aber wenn sie kontrolliert werden kann, warum haben die Riesen sie dann überhaupt in Fesseln gelegt?\n\nSeltsame Logik, nicht?\n\nUm sie zu besiegen, beschwört sie bei den Splittern von Myzrael, wo Ihr zuerst mit ihr spracht. Besiegt sie und sammelt ihre geisterhaften Fesseln ein. Bindet diese dann an die Splitter von Myzrael.\n\nTut das, und sie wird erneut gefangen sein.", objectives = "Geht zu den Splittern von Myzrael, beschwört und besiegt sie.\n\nSammelt ihre geisterhaften Fesseln, und bindet diese an die Splitter von Myzrael.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[657] = { title = "Hinweise auf eine neue Seuche?", description = "<Quae beginnt, den Ordner durchzusehen.>\n\nDas IST interessant. Es scheint, als habe Apotheker Jorell an einigen tödlichen Experimenten hier in Go'Shek gearbeitet. Bin nicht sicher, was das mit Hillsbrad zu tun hat, aber Phin würde es nicht gefallen, wenn wir das einfach so laufen ließen.\n\nWährend Ihr fort wart, hatten wir ein Zusammentreffen mit ein paar Orcs und ich bin nicht in der geeigneten Verfassung, um Kinelory zu helfen. Wenn Ihr es vermögt ... Sie wird Schutz gut gebrauchen können, wenn sie zum Hof geht, um zu stehlen, was Jorell noch nicht nach Tarrens Mühle geschickt hat.", objectives = "Sprecht mit Kinelory.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[658] = { title = "Hinweise auf eine neue Seuche?", description = "Phin hat Euch also geschickt, um nach uns zu sehen? Wundert mich nicht - er macht sich zu viele Sorgen.\n\nWir beobachten den Hof seit Tagen, und Kin sagt, es sei noch gar nicht so lange her, dass sie einen Kurier aus dem kleinen Haus da südlich hat kommen sehen.\n\nSie erzählt viel, aber ich kann ihrem Instinkt immer trauen, wenn wir uns auf gefährlichem Terrain befinden.\n\nIhr seid nicht zufällig ein geschickter Fährtenleser, oder? Wir glauben, dass der Kurier Notizen nach Tarrens Mühle bringen könnte. Wenn wir diese Dokumente in die Hände bekommen könnten, könnten wir vielleicht Näheres über die Vorgänge in Hillsbrad erfahren.", objectives = "Findet den Kurier der Verlassenen und bringt den versiegelten Ordner zu Quae in der Nähe von Go'Sheks Hof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[659] = { title = "Hinweise auf eine neue Seuche?", description = "Seid mir gegrüßt, $N. Ich bin der Anführer einer Abenteurergruppe, die die seltsamen Vorgänge in diesem Gebiet untersucht.\n\nMein Cousin in Hillsbrad musste letztens seinen Hund Stanley einschläfern lassen, weil das Tier seltsamerweise auf eine immense Größe heranwuchs und jeden bösartig angegriffen hat, der ihm näher kam.\n\nIch glaube, dass die Untoten darin verwickelt sind, und wir suchen nach Anzeichen, die das bestätigen.\n\nZwei meiner Kameraden, Quae und Kinelory, haben sich zur Go'Sheks Hof im Arathihochland aufgemacht und haben seit Tagen nichts von sich hören lassen. Könntet Ihr sie für mich finden? Ich mache mir langsam Sorgen.", objectives = "Findet Quae und Kinelory in der Nähe von Go'Sheks Hof im Arathihochland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[660] = { title = "Hinweise auf eine neue Seuche?", description = "Nun gut, $n. Bereit, wenn Ihr es seid.\n\nSollen wir?", objectives = "Beschützt Kinelory bis sie zu Quae zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[661] = { title = "Hinweise auf eine neue Seuche?", description = "Kinelory sah nach einer Nacht in der Taverne schon schlechter aus als jetzt. Ihr habt sie offensichtlich sehr gut beschützt.\n\nDiese Gegenstände, die sie von der Farm mitgebracht hat, sollten Phin zumindest einen Anhaltspunkt davon geben, was in Arathi so vor sich geht. Wir werden hier noch ein Weilchen bleiben, nur um sicherzugehen, dass nach Eurem Angriff kein Gegenschlag kommt. Wärt Ihr bereit, nach Southshore zurückzukehren und mit Phin zu sprechen?", objectives = "Findet Phin Odelic in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[662] = { title = "Tiefsee-Bergung", description = "O'Breen führte die Schiffe in die Bucht. Wir waren ziemlich sicher, dass der Schatz dort zu finden sei. Die HARBINGER konnte noch sicher andocken, aber als die TOLLE MINNA und die SILBERGEIST näher kamen, senkte sich der Meeresspiegel plötzlich ab. So was Seltsames hab ich mein Lebtag nich' gesehn!\n\nDiese beiden Schiffe sind auf irgendetwas aufgelaufen... eine Art Tempel im Riff. Sie sind irre schnell gesunken, eine echte Tragödie.\n\nWir müssen ihre Logbücher und auch ihre Karten wiederbekommen, bevor wir hier wieder weg sind. Wir dürfen diese Informationen nicht einfach für neugierige Augen zurücklassen.", objectives = "Der erste Maat Nilzlix will, dass Ihr die Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST zurückholt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[663] = { title = "Land in Sicht!", description = "Lolo sieht was Winziges, es ist ein $R! Immerzu Ausschau halten, ja, ja, das tut Lolo!\n\nWillkommen in der Faldirbucht. Kapitän O'Breen hat gesagt, dass wir nur für ein paar Stunden hier wären. Grad lang genug, um den Schatz einzusammeln und zurück nach Booty Bay zu segeln.\n\nAber Lolo denkt, dass wir noch sehr lange hier bleiben werden. Wir haben die anderen beiden Schiffe von unserer Formation verloren. Die arme SILBERGEIST und die arme TOLLE MINNA. Sie ruhen jetzt auf dem Grund des Meeres!\n\nLolo schlägt vor, dass Ihr mit Kapitän O'Breen sprecht, wenn Ihr länger hier bleiben wollt.", objectives = "Sprecht mit Kapitän O'Breen in der Faldirbucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[664] = { title = "Ertrunkene Trauer", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne Tolle Minna zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", objectives = "Captain Steelgut in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberhexerinnen der Säbelflossen tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[665] = { title = "Versunkener Schatz", description = "Da wir jetzt richtige Schwarzmeerräuber sind, ist es nun unsere Aufgabe, Herrn O'Breen bei der Suche nach dem verlorenen Elfenschatz behilflich zu sein.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfe im dunklen Meer zu finden. Der Doktor hat eine Schutzbrille konstruiert, die dabei hilft. Er muss die Schutzbrille mit der Energie aufladen, die von dem verzauberten Stein in der Höhle auf dem Hügel dort ausgeht.\n\nAber die Höhle ist verflucht! Sobald wir uns ihr nähern, werden wir überfallen. Wenn Ihr mich verteidigt, kann ich die Energie vom Stein in die Schutzbrille leiten.", objectives = "Begleitet Professor Phizzlethorpe zur Höhle und zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[666] = { title = "Versunkener Schatz", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, $n, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", objectives = "Doktor Draxlegauge in der Faldirbucht will, dass Ihr 10 Elfen-Edelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[667] = { title = "Tod von unten", description = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.\n\nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.\n\nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Booty Bay zurückzufinden.\n\nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.\n\nSeid Ihr bereit, $N?", objectives = "Beschützt Shakes O'Breen während des Angriffs.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[668] = { title = "Versunkener Schatz", description = "Wir sollten Kapitän O'Breen nicht warten lassen. Er wird diese Edelsteine sofort sehen wollen. Darum sind wir ja schließlich hier!\n\nUnd nach ein paar Wochen Zusammenleben mit diesen Piraten sind der Professor und ich zum Schluss gekommen, dass es ganz und gar nicht gut für unsere Gesundheit ist, wenn sie denken, dass wir uns ihre Schätze einverleiben wollen.\n\nHier, $n, bringt das zu O'Breen.", objectives = "Bringt die Elfen-Edelsteine zu Kapitän O'Breen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[669] = { title = "Versunkener Schatz", description = "Flottenmeister Seehorn will über unseren Fund sofort informiert werden.\n\nAber, wie Ihr selbst sehen könnt, sind wir nicht unbedingt in der Lage, von hier wegzukommen. Es ist nicht nur der zu niedrige Wasserstand, sondern auch diese verdammten Viecher, die wir gestört haben, und die jetzt jede unserer Bewegungen aufs Genaueste beobachten.\n\nIhr könnt den Schwarzmeerräubern einen sehr großen Dienst erweisen, wenn Ihr Flottenmeister Seehorn in Booty Bay davon in Kenntnis setzen könntet, dass wir den Schatz gefunden haben und dabei sind, weitere Steine zu bergen. Bringt ihm diese Probe zum Beweis.", objectives = "Bringt die Probe zu Flottenmeister Seehorn nach Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[670] = { title = "Versunkener Schatz", description = "Sagt, $n, Ihr seht aus wie jemand, der einem Abenteuer nicht abgeneigt ist. Meine Flotte liegt hier in Booty Bay fest, bis wir unsere Vorräte auffüllen können.\n\nHier und auch außerhalb braut sich so einiges zusammen und ich muss ein paar äußerst geheime Nachrichten an Shakes O'Breen übermitteln, der vor der Arathi-Küste festsitzt.\n\nKann ich auf Euch vertrauen, dass Ihr diese Nachricht sicher und unberührt überbringt?", objectives = "Bringt Seehorns Brief zu Kapitän O'Breen im Arathihochland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[671] = { title = "Elende Magien", description = "Ich fühlte etwas Fremdes in der Luft... ein Gefühl, das mein Blut köcheln lässt. Ich hatte auch schon einen Verdacht. Ich bin ausgezogen, um die Quelle meiner Unruhe aufzuspüren, und im Northfold-Anwesen im Westen fand ich restliche Spuren einer Dämonenbeschwörung. Als ich näher kam, begann mein Blut zu sieden und die Wut in mir wuchs.\n\nAuf dem Boden entdeckte ich ein Blutsteinamulett, das bei Dämonenbeschwörungen als Hilfe benutzt wird. Das Amulett, das ich fand, war jedoch entleert. Ich benötige ein weiteres, um es zu untersuchen, aber ich wage nicht, zum Anwesen zurückzukehren. Könnt Ihr mir ein paar bringen?", objectives = "Holt 10 Blutsteinamulette für Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[672] = { title = "Mut machen", description = "Wir haben versucht, es ihm gemütlich zu machen, ihn aufzumuntern, haben ihm Geschichten erzählt von unserer mächtigen Stadt in Orgrimmar in Kalimdor, aber nichts, gar nichts hat ihn berührt.\n\nGeschichten von unserem jungen Kriegshäuptling, Thrall, der die Rüstung und den Hammer von Orgrim trägt... aber vielleicht... Vielleicht! Eine kleine Demonstration von unserer neu gefundenen Schamanen-Magie könnte ihm neue Hoffnung geben. Einen Versuch ist es wert!\n\nEin kleines Objekt könnten wir für ihn machen, ja... Bringt mir ein paar Raptoraugen und ich werde sehen, was ich tun kann.", objectives = "Bringt 10 Hochlandraptorenaugen von Hochlandschreitern und Hochlandhauern zu Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[673] = { title = "Elende Magien", description = "Ich habe keinerlei Zweifel, dass ein mächtiger Hexenmeister sich innerhalb der Mauern Stromgardes aufhält. Von Zeit zu Zeit hat dieser Hexenmeister mit Hilfe eines arkanen magischen Relikts abscheuliche Dämonen in großer Zahl herbeibeschworen. Wir müssen ihm die Quelle seiner Energie nehmen.\n\nSucht den Hexenmeister und tötet ihn. Bringt mir alle magischen Objekte, die Ihr bei ihm finden könnt, und ich werde die geeigneten Schritte unternehmen, sie zu zerstören, damit ihre Macht nicht mehr dazu benutzt wird, dieses Land weiterhin zu besudeln.", objectives = "Bergt Marez Cowls Blutsteinkugel und bringt sie zu Tor'gan in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[674] = { title = "Mut machen", description = "Hier, übergebt dieses Amulett Gor'mul und beobachtet, ob die Kraft der Raptoren das Feuer des Kriegers, das einst in seinen Adern brannte, erneut erwecken kann.", objectives = "Gebt das Raptorkrallen-Amulett an Gor'mul.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[675] = { title = "Mut machen", description = "<Gor'mul wirft das Amulett zu Boden.>\n\nTor'gans hat Euch geschickt, oder? Pah! Warum er mir gegenüber Gnade empfindet, geht über meinen Verstand. Gnade wurde mir verweigert, als es mir nicht vergönnt war, mit meinem Kriegshäuptling im Kampf zu sterben. Das Schicksal hat mir einen harten Schlag versetzt ...", objectives = "Sprecht mit Tor'gan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[676] = { title = "Der Hammer kann fallen", description = "Schwächlinge... alle miteinander. Ihr da, $C, was schaut Ihr so dämlich? Denkt wohl, Ihr seid was Besonderes, was? Wollt Ihr's nicht mal beweisen?\n\nDer Außenposten von Hammerfall in Arathi wird angegriffen. Wenn wir der Besatzung nicht bald Hilfe schicken, steht ihr Ableben unmittelbar bevor.\n\nAber bevor Ihr jetzt einfach losrennt, möchtet Ihr vielleicht Eure Fähigkeiten erst testen. Nordöstlich von Stromgarde in Arathi befindet sich ein Ogerhort, der von den Felsfaustogern bewohnt wird. Wenn Ihr die Oger und Vollstrecker dort in den Griff bekommt, erstattet Drum Fel in Hammerfall Bericht.", objectives = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste und sucht dann Drum Fel im Außenposten von Hammerfall im Arathihochland auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[677] = { title = "Zu den Waffen", description = "Die Trolle der Witherbark und die Felsfaustoger von Arathi arbeiten zusammen daran, uns von diesem Land zu vertreiben, aber unser Schicksal liegt weder in ihren noch in irgendwessen anderen Händen. Wir werden sie erledigen und ihnen zeigen, dass dies auch unsere Heimat ist. \n\nDie Trolle haben sich von uns abgewandt, die Oger würden uns als Nahrung und Bettvorleger benutzen, wenn wir es zuließen - das darf nicht sein.\n\nWir werden unseren Angriff auf die Trolle der Witherbark südlich von hier beginnen. Erschlagt sie in Scharen und kehrt erst zurück, wenn ihre Lager dick mit Blut bedeckt sind.", objectives = "Erschlagt 10 Axtwerfer der Witherbark, 10 Kopfjäger und 8 Hexendoktoren und kehrt zu Drum Fel im Außenposten von Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[678] = { title = "Zu den Waffen", description = "Eure Kraft ist offensichtlich, $n. Dann zeigt mal, wie Ihr Euch mit echten Feinden schlagt.\n\nDie Felsfaustoger haben einen Unterschlupf südwestlich von hier, Richtung der Zwergenbrücke, und, wenn ich mich nicht täusche, werden die Raufer und Magi dort eine etwas größere Herausforderung darstellen - für uns waren sie das bislang zumindest.\n\nErschlagt so viele wie Ihr irgend könnt und kommt persönlich zu mir, wenn Ihr erfolgreich seid, oder erscheint mir als Geist, wenn Ihr versagt. Ich werde Eure Beharrlichkeit in der Schlacht in jedem Falle preisen.", objectives = "Tötet 10 Schläger der Felsfäuste und 4 Magi der Felsfäuste und sucht dann Drum Fel im Außenposten von Hammerfall auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[679] = { title = "Zu den Waffen", description = "Der Kopf der Bestie kann abgetrennt werden... mit einem mächtigen Schlag, $n. Ihr habt alle Zeichen dafür gezeigt, dass Ihr in der Lage seid, uns mit diesem letzten mächtigen Schlag zu helfen. Die Anführer dieser Angriffe haben ihren Unterschlupf innerhalb der Ruinen von Stromgarde gewählt, einem grellen Symbol menschlicher Schwachheit.\n\nFindet und erschlagt diese Lords der Felsfäuste und ihre speichelleckenden Schamanen, die versuchen, uns aus diesem Land zu vertreiben.", objectives = "Tötet 15 Schamanen der Felsfäuste und 10 Lords der Felsfäuste und kehrt zu Drum Fel im Außenposten von Hammerfall im Arathihochland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[680] = { title = "Die echte Bedrohung", description = "Ihr seid meinem Gemahl ein treuer Diener, $C, aber er weiß nicht, warum Hammerfall angegriffen wird.\n\nOr'Kalar, Mugh'thols Helfer in Stromgarde hasst meinen Gemahl aufs Äußerste, und er wünscht sich nichts mehr, als ihn tot zu sehen, da mein Gemahl ihn vor Jahren einmal besiegte.\n\nDie Vorzeichen verrieten mir, dass Or'Kalar eine Falle für meinen Gemahl ausgelegt hat. Aus diesem Grund habe ich Hinweise auf den Aufenthaltsort des Ogers vor ihm versteckt.\n\nMein Gemahl wird Hals über Kopf losschlagen, sobald er vom Aufenthaltsort des Ogers erfährt, und ich wollte Eure Hilfe bei der Tötung der Kreatur erbitten.", objectives = "Erschlagt Or'Kalar und bringt seinen Kopf zu Korin Fel in den Außenposten von Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[681] = { title = "Northfold-Anwesen", description = "Wir kämpfen einen Kampf um Stromgarde, und wir verlieren ihn. Die Oger, das Syndikat und wir haben unsere einst große Stadt geteilt und jede Fraktion bekämpft die andere bis zu einem blutigen Unentschieden.\n\nAber unsere Streitkräfte schwinden, während unsere Feinde immer stärker werden.\n\nWir brauchen Hilfe aus der Stadt Southshore, aber Vorräte sind nur schwer zu bekommen, solange das Syndikat das Gebiet zwischen uns kontrolliert.\n\nBegebt Euch zum Syndikatsstützpunkt im Northfold-Anwesen und tötet sie alle. Dann wird der Druck auf unsere Versorgungszüge ein wenig nachlassen und ein größerer Teil wird durchkommen.", objectives = "Tötet 10 Straßenräuber des Syndikats und 6 Söldner des Syndikats.\n\nKehrt zu Captain Nials bei der Zuflucht zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[682] = { title = "Abzeichen von Stromgarde", description = "Das Syndikat in Stromgarde bekämpft das Kontingent unserer Miliz dort. Um diesen Pöbel dazu zu bringen, sich mit unseren disziplinierteren Streitkräften zu schlagen, haben die Syndikatsanführer ein Kopfgeld auf unsere Soldaten ausgesetzt und belohnen jedes Abzeichen von Stromgarde, das toten Milizleuten abgenommen wurde, mit Gold.\n\nWir wollen diese Abzeichen zurück - wir dürfen es diesen Halsabschneidern nicht erlauben, Trophäen von unseren mutigen Gefallenen zu rauben!\n\nBegebt Euch in das vom Syndikat kontrollierte Gebiet von Stromgarde und jagt ihnen unsere Abzeichen ab.", objectives = "Bringt Abzeichen von Stromgarde zu Captain Nials bei der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[683] = { title = "Sara Balloos Hilfegesuch", description = "$n, ich habe nur eine kleine Bitte an Euch.\n\nBringt diese Mitteilung, die ich vorbereitet habe, zu unserem großen Monarchen von Ironforge, König Magni Bronzebeard. Es ist fast lächerlich, diese kleine Aufgabe von Euch zu verlangen, von jemandem, der für die Sache der Allianz bislang eine so große Unterstützung war.\n\nAber in meinem von Trauer übermannten Zustand vor den König zu treten, wäre meinem Anliegen nicht im Geringsten dienlich. Das versteht Ihr sicher.", objectives = "Bringt Sara Balloos Notiz zu König Magni Bronzebeard von Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[684] = { title = "GESUCHT: Marez Cowl", description = "Es wurde ein Kopfgeld auf Marez Cowl ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Captain Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie sich mit Dämonen abgibt. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", objectives = "Bringt Marez' Kopf zu Captain Nials bei der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[685] = { title = "GESUCHT: Falkenstein und Otto", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein zeichnet für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Captain Nials abgeholt werden.", objectives = "Bringt Ottos und Falkensteins Köpfe zu Captain Nials bei der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[686] = { title = "Ehrerbietung von einem König", description = "Ich erwarte nicht, dass Zwerge wie die gute Frau Balloo es verstehen, warum so ein Krieg für das größere Wohl unseres Volkes ertragen werden muss. Der Verlust ihres Gemahls und der Verlust jedes einzelnen Zwerges, der im Namen der Allianz kämpft, lastet schwer auf meiner Seele.\n\nAuch wenn ich nicht in der Lage bin, ihren Gemahl aus dem wirbelnden Nether zurückzuholen, so kann ich ihm doch meine Ehrerbietung erweisen. \n\nIch werde einen Gedenkstein für Sully Balloo bei Großsteinmetz Marblesten in Auftrag geben.\n\nBenachrichtigt ihn sofort, $C. Ihr werdet die Durchführung meines Auftrags beaufsichtigen.", objectives = "König Magni Bronzebeard will, dass Ihr mit Großsteinmetz Marblesten sprecht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[687] = { title = "Theldurin der Verirrte", description = "Theldurin der Verirrte war einst ein Mitglied unseres Ordens, dem Twilight-Hammer. Aber er wurde verrückt und hat unsere Lehren verdammt. Bevor er uns davonlief, hat er die Rolle von Myzrael gestohlen! Wir konnten ihn nicht einfangen, aber Gerüchte besagen, dass er sich im Ödland versteckt, sabbelnd und wahnsinnig.\n\nIhr müsst die Rolle finden, denn nur so könnt Ihr die Fürstin zu uns zurückbringen. Und dafür müsst Ihr Theldurin finden.", objectives = "Findet Theldurin den Verirrten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[688] = { title = "Myzraels Verbündete", description = "<Myzrael spricht.>\n\nFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einsperren.\n\nAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangene gehalten zu haben!\n\nIhr seid ein edelmütiger Verbündeter, $n. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, werdet Ihr mich an die Oberfläche beschwören müssen.\n\nSprecht mit Zaruk in Hammerfall. Er weiß, wie ich beschworen werden kann.", objectives = "Sprecht mit Zaruk in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[689] = { title = "Ehrerbietung von einem König", description = "Unser guter König will also, dass wir einen Gedenkstein zu Ehren eines Soldaten mit Namen Sully Balloo errichten? Und Ihr sagt, dass der arme Kerl bei der Tragödie am Thandol-Übergang gestorben sei?\n\nBah, wird denn jemals Frieden auf Azeroth herrschen?\n\nWie dem auch sei, ein Auftrag vom König hat die allerhöchste Priorität. Und um ein wahrhaft episches und bleibendes Werk zu schaffen, will ich mit dem besten Stein arbeiten, der verfügbar ist. Begebt Euch nach Darrow Hill in Hillsbrad und besorgt mir etwas Alteracgranit.", objectives = "Großsteinmetz Marblesten aus Ironforge will 5 Stücke Alteracgranit.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[690] = { title = "Malins Gesuch", description = "Seid gegrüßt, $N. Ihr seht aus wie ein Abenteurer und ich habe eine Aufgabe, die erledigt werden muss.\n\nErzmagus Trelane, mein früherer Meister, ist vor nicht allzu langer Zeit aus Stromgarde im Arathihochland geflohen und er hat mich gebeten, bei der Wiederbeschaffung einiger Gegenstände, die er zurückließ, behilflich zu sein.\n\nDie Stadt wird belagert und er hat versucht, den Turm von Arathor zu verteidigen, aber ohne Erfolg. Ich habe bereits Agenten im Hochland, aber sie haben mich gebeten, weitere Hilfe zu schicken. Seid Ihr interessiert?", objectives = "Sucht Skuerto bei der Zuflucht im Arathihochland auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[691] = { title = "Das Gewicht in Gold wert", description = "Erzmagier Malin schickte Skuerto und mich hierher, um für ihn ein paar Reagenzien zu besorgen. Ich hatte keine Ahnung, wie ich die Gegenstände beschaffen sollte, aber da Ihr jetzt hier seid, hat sich mein Problem wohl gelöst.\n\nIch brauche Folgendes: Hauer der Witherbark, Medizinbeutel der Witherbark und ein Schattenjägermesser.\n\nKönntet Ihr mir das besorgen? Die Witherbark leben südöstlich von Arathi.", objectives = "Sucht für Lehrling Kryten bei der Zuflucht 10 Hauer der Witherbark, 4 Medizinbeutel der Witherbark und 1 Schattenjägermesser.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[692] = { title = "Die verlorenen Fragmente", description = "Die Rolle von Myzrael... die Rolle von Myzrael?! Die wollt Ihr doch wohl nicht haben! Ihre Magie kann Myzrael an die Oberwelt locken, und wenn Ihr das tut, sind wir alle in Gefahr!\n\nOder... vielleicht ist es schon zu spät. Vielleicht ist sie schon frei. Vielleicht sammelt sie nur ihre Kraft, bevor sie sich auf uns stürzt. Wenn es so ist, BRAUCHT Ihr die Rolle!\n\nZu dumm, dass sie zerstört wurde. Wütende Elementare haben sie gestohlen und kämpfen jetzt um die Fragmente.\n\nWenn Ihr diese Fragmente jedoch sammeln könntet, können wir sie vielleicht wieder zusammensetzen...", objectives = "Bringt Theldurin dem Verirrten das zerrissene Rollenfragment, das zerknüllte Rollenfragment und das angesengte Rollenfragment.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[693] = { title = "Zauberstab gegen Faust", description = "He, $N. Tut mir Leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandol-Übergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", objectives = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[694] = { title = "Trelanes Verteidigung", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen die Verteidigungsanlagen des Turms aktivieren, wenn wir eine Chance gegen sie haben und es lebend zu den Gegenständen schaffen wollen. Dazu brauchen wir ein paar Edelsteine, an denen die Schamanen der Felsfäuste Gefallen gefunden haben. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann, sodass sie wie ein Schlüssel funktionieren.", objectives = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten bei der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[695] = { title = "Des Lehrlings Verzauberung", description = "Bitte sehr, $N. Der Edelstein muss nur gegen einen der Sockel nahe dem Fuß des Turms gepresst werden, um dessen Verteidigung zu aktivieren. Benutzt ihn, wenn Ihr bereit seid, den Turm zu betreten und nach den restlichen Gegenständen Trelanes zu suchen. \n\nViel Glück. Ich warte hier im Lager auf Eure Rückkehr. Oh, und sprecht mit Skuerto, bevor Ihr geht. Er gibt Euch die restlichen Details, die Ihr braucht.", objectives = "Sprecht mit Skuerto.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[696] = { title = "Angriff auf den Turm", description = "Danach müsst Ihr suchen: Trelanes Phylakterium, Trelanes Kugel, Trelanes Glutachat.\n\nAlle drei Dinge sollten sich innerhalb des Turms in Truhen befinden und es sollte Euch keine Schwierigkeiten bereiten, diese Truhen selbst zu öffnen; Ihr müsst Euch nur vor den Ogern in Acht nehmen.\n\nDie Verteidigungen des Turms kümmern sich nicht selbstständig um die Oger, Ihr müsst Eure Waffen jederzeit griffbereit haben. Wenn diese Oger herausfinden, dass Ihr dort seid, um sie zu bestehlen, werden sie Euch in die Mangel nehmen.\n\nSeid vorsichtig - und viel Glück.", objectives = "Sucht Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt ihn Skuerto bei der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[697] = { title = "Malins Gesuch", description = "Bringt diesen Brief nach Stormwind und lasst Malin wissen, dass Kryten und ich bald wieder zu Hause sind. Ich zweifle nicht daran, dass er Euch reichlich für Eure Hilfe uns gegenüber belohnen wird, $N.\n\nSichere Reise.", objectives = "Bringt dem Erzmagier Malin im Magierviertel von Stormwind den versiegelten Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[698] = { title = "Mangelnde Reserven", description = "Ich versuche, einige Vorräte für unseren Außenposten in der Nähe des Strandes im Osten zusammenzutragen - Tok'Kar tut, was er kann, aber neben dem Dienst als Wache und Kochen für seine Soldaten ist nicht mehr viel Zeit übrig vom Tag.\n\nWann immer sie können, kochen sie dort mit Begeisterung Sägezahnfleisch, aber ich hatte einfach keine Zeit, ihnen eine neue Ladung rüberzuschicken. Würdet Ihr mir da aushelfen?\n\nDie jungen Sägezähne sind nicht so schmackhaft wie die älteren, macht also einen Bogen um sie; gebt ihnen ein oder zwei Jahre, um zur vollen Größe heranzuwachsen.", objectives = "Bringt Tok'Kar in den Sümpfen des Elends 8 Stück unverarbeitete Sägezahnflanken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[699] = { title = "Mangelnde Reserven", description = "Man hat uns wegen der Murlocplage entlang der Küste hier stationiert, um andere vor Gefahren jeglicher Art, die Stonard bedrohen könnten, zu beschützen - oder zu warnen, falls deren Streitkräfte zu groß werden. Das gibt uns nicht viel Zeit, um auszuruhen, und wir könnten weitere Hilfe Eurerseits gebrauchen, wenn Ihr gewillt seid.\n\nDie Sägezahnschnapperklauen geben erstklassige Waffen ab, wenn sie richtig vorbereitet werden. Bringt mir ein paar ihrer Klauen, dann werde ich zusehen, dass Ihr eine unserer Waffen als Dank für das Frischfleisch und die angenehme Gesellschaft bekommt.", objectives = "Bringt Tok'Kar in den Sümpfen des Elends 6 Sägezahnschnapperklauen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[700] = { title = "Ehrerbietung von einem König", description = "Ah, welch edle Steine doch aus Lordaeron kommen. Was für eine Schande, dass in diesem Land ein solches Chaos herrscht.\n\nAber der Gedenkstein ist sehr schön geworden! Ich glaube, der König wird damit sehr zufrieden sein.\n\nWürdet Ihr so gütig sein und Seiner Majestät eine Nachricht senden, dass der Gedenkstein wie gefordert fertig gestellt wurde?", objectives = "Erstattet Meldung an König Magni Bronzebeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[701] = { title = "Arglist des Raptors", description = "Mit ein paar weiteren Dingen kann ich einen Gegenstand schaffen, der Gor'mul mit der Magie der Arglist des Raptors erfüllt! Wenn ihn die Macht des Raptors durchströmt, wird Gor'mul unsere neue Macht erkennen und den Krieger neu entdecken, der in ihm schlummert!\n\nUm den Gegenstand und den Zauber zu schaffen, werden Raptorherzen benötigt.", objectives = "Besorgt für Tor'gan 12 Raptorherzen von Hochlandfleischpirschern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[702] = { title = "Arglist des Raptors", description = "Nehmt diese Kugel und nutzt ihre Energie, um Gor'mul die Essenz des Raptors zu spenden. Sie wird seinen Geist erfrischen und ihm einen neuen Lebensinhalt geben. Sobald er wieder normal ist, können wir ihn über die aktuelle Situation der Horde informieren und wir werden einen großen Krieger bei unseren unaufhörlichen Kämpfen an unserer Seite haben.", objectives = "Gebt Gor'mul Tor'gans Kugel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[703] = { title = "Gegrillte Bussardflügel", description = "Oh ja, meine gegrillten Bussardflügel sind ein Renner! Die Sauce ist gehaltvoll und das Fleisch würzig. Und der Duft lockt alle hungrigen Mäuler in einem Umkreis von Meilen an!\n\nIch habe alles, was ich brauche, um eine Menge zu kochen. Alles... außer Bussardflügel!\n\nWenn Ihr etwas davon haben möchtet, besorgt mir Bussardflügel. Bringt Ihr mir genügend davon, gebe ich Euch vielleicht sogar das Rezept dafür!", objectives = "Bringt Rigglefuzz 4 Bussardflügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[704] = { title = "Agmonds Schicksal", description = "Der letzte Bericht, den ich von Agmond erhalten habe, ist sehr beunruhigend, umso mehr, da er jetzt tot ist! Er erwähnte, dass seine Buddler an der Grabungsstätte vor Uldaman \"uralte Urnen\" entdeckt hätten. Ich fürchte, dass die dort gefundenen Urnen die Troggs erzürnt haben, ebenso wie die Götzen, die ich dort fand.\n\nIch möchte, dass Ihr uns die Urnen bringt, damit wir sie untersuchen können. Geht zur Grabungsstätte Uldaman, sammelt die Urnen ein und kehrt dann zu mir zurück.", objectives = "Bringt Ausgrabungsleiter Ironband am Loch Modan 4 verzierte Steinurnen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[705] = { title = "Perlentauchen", description = "Das Ödland ist eine unwirtliche Gegend voller heimtückischer Raubtiere und dreister Aasfresser. Unheimlich, besonders für einen so kleinen Goblin. Ich muss gewitzt sein, wenn ich überleben möchte!\n\nIch kenne das Rezept für Blitzstrahlbomben. Die benutze ich, um wilde Tiere zu verjagen. Leider geht mir langsam eine der Zutaten aus: zu Pulver zermahlene blaue Perlen. Bringt mir welche, dann soll es Euer Schaden nicht sein.\n\nHe, und ich hoffe, Ihr habt gute Stiefel an. Die blauen Perlen, die ich brauche, stammen von Muscheln am finsteren Riff.\n\nGenau, dem finsteren Riff im Schlingendorntal!", objectives = "Bringt Rigglefuzz im Ödland 9 blaue Perlen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[706] = { title = "Feuerverzauberungen", description = "Als Lehrling Feranor Steeltoes habe ich seine Spezialtechnik erlernt, wie man feurige Verzauberungen auf Waffen wirkt. Als ich das letzte Mal von ihm hörte, arbeitete er mit einer Jägergruppe in einer Schmiede, oben in Lordaeron.\n\nIch kann Euch nicht viel darüber sagen, an was genau er dort arbeitete, nur dass dazu Blut eines noch schlagenden Herzens eines seltenen Schwarzdrachen-Welpen nötig ist. Ohne Neuigkeiten aus Ironforge habe ich nicht viel zu tun. Wenn Ihr mir ein Herz eines Welpen aus der Lethlorklamm bringt, zeige ich Euch meine Fertigkeiten!", objectives = "Besorgt Sigrun Ironhew ein Schwarzdrachenherz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[707] = { title = "Ironband sucht Euch!", description = "$N. Ich habe Berichte von Ausgrabungsleiter Ironband von der Ausgrabungsstätte am Loch Modan erhalten - er braucht jemanden, der ihm die Rennerei auf einer unserer anderen Ausgrabungen abnimmt.\n\nIch habe keine weiteren Details, aber wenn Ihr Euch ein bisschen die Füße vertreten wollt, dann sprecht mit Ironband.", objectives = "Sprecht auf Ironbands Ausgrabungsstätte am Loch Modan mit Ausgrabungsleiter Ironband.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[708] = { title = "Der Flugschreiber", description = "Die Oberfläche dieses metallenen Flugschreibers ist stark angegriffen, so, als hätte man ihn in Säure getaucht... er muss lange im Magen des Riesenkondors gelegen haben.\n\nIhr dreht die Kiste um und entdeckt ein Symbol, das in den Boden eingeprägt ist. Unter dem Symbol stehen folgende Wörter:\n\n\"Motor Nr. 19 - Belagerungsbrigade von Eisenschmiede\"", objectives = "Bringt den zerfressenen Flugschreiber in die Halle der Waffen in Eisenschmiede.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[709] = { title = "Lösung der Verdammnis", description = "Oh je! Oh je! Unheil naht! Hört auf mich! Unheil!\n\nNein, ich darf nicht darüber sprechen... darf nicht ihre Namen aussprechen, sie könnten mich hören! Aber wenn wir mehr über sie lernen, ja, mehr... dann könnten wir vielleicht lernen, wie man sie aufhalten kann!\n\nVielleicht.\n\nGeht nach Uldaman. Nein! Ich hab's gesagt! Ihr müsst... die Schrifttafel von... Ryun'eh finden. Ja, findet sie! Und bringt mich nicht dazu, diesen Namen noch einmal auszusprechen!\n\nSie ist verborgen an diesem Ort, in einer uralten Truhe. Da ist sie versteckt... in einer Truhe, die gefertigt wurde, lang bevor Zwerge solche Werke vollbrachten.", objectives = "Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[710] = { title = "Element-Studie: Fels", description = "Ich habe die Arbeit an meinem neuesten Projekt hier im Ödland erst mal eingestellt: meine Fesseln der Elementarbindung.\n\nWenn sie vollendet sind, werden Magier noch mächtigere Elementare beschwören und sie in noch größerer Zahl nutzen können. Ich brauche zunächst kleine Felssplitter, um einige meiner neuesten Angriffszauber und ein paar der Dingsdas zu testen, die ich zusammengebastelt habe.\n\nDie Splitter kann man leicht von den kleinen Felselementaren westlich von hier sammeln. Würdet Ihr mir ein paar bringen?", objectives = "Sucht 10 kleine Felssplitter und bringt sie Lotwil Veriatus im Ödland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[711] = { title = "Element-Studie: Fels", description = "Ihr habt Euch als fähiger erwiesen als all meine Lehrlinge zusammen, $n.\n\nFür die nächsten Aktionen ist etwas mehr Krafteinsatz erforderlich. Wenn Ihr vorsichtig genug seid, könnt Ihr bei Felselementaren große Steinplatten finden. Ihre Körper sind kräftiger und größer und deshalb kommt man bei ihnen eher an Teile heran, die groß genug für meine Tests sind. Ihr findet sie weiter westlich von hier oder südöstlich entlang des Gebirgsrandes.\n\nLasst Euch Zeit, ich brauche eine Weile, um diese kleineren Stücke zu testen, die Ihr mir gebracht habt.", objectives = "Bringt Lotwil Veriatus im Ödland 3 große Steinplatten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[712] = { title = "Element-Studie: Fels", description = "$n, ich brauche noch ein weiteres Teil von den Elementaren hier im Ödland: die Armschienen der Steinbindung von den großen Felselementaren. Meinen Berechnungen nach sollten diese Armschienen ausreichen, um die Kraft meiner Fesseln zu beurteilen.\n\nBei meinen Wahrsageversuchen über die großen Felselementare sah ich eine Gruppe von ihnen südwestlich von hier, in der Nähe von ein paar Ogern, wenn ich mich recht erinnere.\n\nBringt mir 5 ihrer Armschienen, damit ich ein paar in Reserve habe. Servo ist berüchtigt dafür, meine Reagenzien und Forschungen zu verlegen.", objectives = "Bringt Lotwil Veriatus im Ödland 5 Armschienen der Steinbindung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[713] = { title = "Kühlaufsätze setzen sich durch", description = "Lasst mich Euch etwas über Frostöl erzählen: Nichts kann einen Motor oder ein Getriebe besser vor Überhitzung schützen.\n\nSeine Kühleigenschaften sind außerordentlich und seine Langlebigkeit als Schmiermittel ist ohnegleichen. Aber das ist nicht alles: Es trägt auch dazu bei, die Verzauberung magischer Gegenstände zu erhalten.\n\nIch brauche eine Phiole davon, um die magische Kapazität meiner Fesseln zu erhöhen und sie mächtig genug zu machen, um unseren beschworenen Freund davon abzuhalten, uns alle umzubringen.\n\nBro'kin, einer meiner Goblin-Freunde, kann Euch lehren, wie man es herstellt. Er wohnt in Alterac.", objectives = "Sucht Frostöl und bringt es Lotwil Veriatus im Ödland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[714] = { title = "Gyro... Was?", description = "Ihr habt Eure Arbeit überdurchschnittlich gut gemacht, $n.\n\n<Lotwil ist offensichtlich durch seine Arbeit abgelenkt.>\n\nFalls wir uns in Kharanos jemals wiedersehen, scheut Euch nicht, zu mir zu kommen und nach Arbeit zu fragen.\n\nUpps! Schnell, nehmt das... ja, das da. Danke.\n\nJetzt brauche ich nur noch eines. Es ist ein kleines Teil, aber leider ziemlich ausschlaggebend: ein Gyrochronatom.\n\nWenn Ihr irgendwo einen auftreiben und mir bringen würdet, könnte ich das hier fertig stellen.", objectives = "Bringt Lotwil Veriatus im Ödland einen Gyrochronatom.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[715] = { title = "Flüssigstein", description = "Ich glaube, die Gegenstände, die Ihr Lotwil besorgt habt, werden unsere geringste Sorge sein, $n. Andererseits habt Ihr Euch in den Wissenschaften, die Lotwil so heilig sind, mehr als talentiert gezeigt; also wie wäre es, wenn Ihr jetzt mir ein bisschen helft?\n\nIch brauche einen Unsichtbarkeitstrank und einen Heiltrank; beides könnte sich als nützlich erweisen, sobald er erst mit seinem Ding angefangen hat.\n\nDafür gebe ich Euch dieses Rezept für einen Trank, den ich entwickelt habe, als ich noch bei Lotwil in die Lehre ging. Er basiert auf einigen der Forschungen, die er hier im Ödland durchführte.", objectives = "Bringt Lucien Tosselwrench im Ödland einen Heiltrank und einen geringen Unsichtbarkeitstrank.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[716] = { title = "Stein ist besser als Stoff", description = "Ich weiß, wie knickerig Lotwil sein kann, $n, also lasst mich etwas als Belohnung für all Eure Mühen fertigen. Vielleicht kann es Euch sogar vor der Scheußlichkeit schützen, die Lotwil gerade erfindet.\n\nIch habe alle zusätzlichen Steine verarbeitet, die Ihr für ihn gesammelt hattet, und kann Euch ein paar hübsche Armschienen machen, die Ihr möglicherweise gebrauchen könnt. Sie sind natürlich verzaubert.\n\nIch brauche nur noch gemusterte bronzene Armschienen, die ein Schmied hergestellt hat, um die fertig zu stellen, die ich für Euch mache.", objectives = "Bringt Lucien Tosselwrench im Ödland einige gemusterte bronzene Armschienen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[717] = { title = "Erdbeben", description = "Es ist offensichtlich, dass wir nicht mehr gewährleisten können, Schattenbringer und Hematus noch länger in Lethlor festzuhalten. Die schwarzen Großdrachen haben sich dort niedergelassen, und dass es den Ogern gelungen ist, das Zeichen zu stehlen, weist darauf hin, dass drastischere Maßnahmen ergriffen werden müssen.\n\nDas Gefängnis der Drachen wird von drei Runensteinen gebildet, die man nur mit Hilfe des Zeichens der Erde wegnehmen kann. Diese Runensteine können dann dazu verwendet werden, das Siegel zu zerbrechen, das sie gefangen hält.\n\n$N... sorgt dafür, dass sie süß träumen... für immer.", objectives = "Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.\n\nLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.\n\nTötet sie und bringt dann Garek Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[718] = { title = "Illusionen", description = "Wir hatten es so eilig, die Ausgrabungsstätte von Uldaman zu verlassen, dass wir uns gezwungen sahen, unterwegs viele Wagen und Nachschubkisten zurückzulassen. Die Oger von Camp Kosh haben sich auf unsere zurückgelassene Ausrüstung gestürzt wie Geier auf faulende Kadaver. Riechen auch nicht besser. Als die Kadaver, meine ich.\n\nWie dem auch sei, sie haben sich den Wagen mit unseren Waffen und anderem Zeug geschnappt und deshalb - tja, es ist ein bisschen peinlich - konnten wir uns nichts zum Essen beschaffen.\n\nWir stecken echt ganz schön in der Klemme. Könnt Ihr uns vielleicht helfen?", objectives = "Holt die Nachschubkiste für Sigrun Ironhew.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[719] = { title = "Ein Zwerg und sein Werkzeug", description = "He, $N. Seid lieber vorsichtig. Es sind Dunkeleisenzwerge in der Nähe - scheinen vom Schattenschmiedeklan zu sein.\n\nSie haben gerade die Ausgrabungsstätte angegriffen, auf der ich arbeite - haben fast alle dort umgebracht, darunter meinen Boss Hammertoe. Ich bin gerade noch lebendig weggekommen.\n\nDie Stätte liegt nördlich von hier und ich versuche, mir einen Plan auszudenken, wie wir einen Teil unserer Vorräte zurückbekommen könnten, insbesondere meine Glückshacke.\n\nMeint Ihr, Ihr könntet mir ein bisschen helfen? Einer von diesen verdammten Dunkeleisenzwergen muss meine Hacke haben! Es könnte jeder von denen sein.", objectives = "Sucht Ryedols Glückshacke und bringt sie Ausgrabungsleiter Ryedol in der Hammertoe-Grabungsstätte.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[720] = { title = "Ein Hoffnungsschimmer", description = "<Text wurde mit Kreide auf die Karte gekritzelt.>\n\n\"Ryedol, \nSie bringen mich nach Uldaman. Schickt Hilfe.\n- Hammertoe\"", objectives = "Sucht Ausgrabungsleiter Ryedol und teilt ihm mit, dass Hammertoe Grez noch am Leben ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[721] = { title = "Ein Hoffnungsschimmer", description = "$N, geht Ihr ihn suchen? Sucht Ihr Hammertoe in Uldaman?\n\nWenn diese dreckigen Zwerge der Schattenschmiede ihn als Geisel genommen haben, um herauszubekommen, was er über die Titanenausgrabungen weiß, könnte ganz Ironforge in großer Gefahr sein.\n\nSeit langer Zeit schon trachten die Dunkeleisenzwerge nach Magie, um noch mächtigere Golems zu erschaffen. Hammertoe hatte dasselbe vor, aber natürlich nur, um sie aufzuhalten.\n\nVielleicht lassen sie ihn am Leben, bis sie herausbekommen haben, was er weiß; Ihr müsst Euch beeilen, wenn Ihr ihn retten wollt!", objectives = "Sucht in Uldaman nach Hammertoe Grez.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[722] = { title = "Amulett der Geheimnisse", description = "Ihr seid mutig... (((hustet))) dass Ihr Euch wegen mir nach Uldaman wagt, $C.\n\nWenn Ihr wirklich hier seid, um dem... ollen Hammertoe zu helfen, dann... (((hustet)))... müsst Ihr nach... meinem Amulett suchen.\n\nGrubenschatten hat es... Magregan Grubenschatten. Muss hier irgendwo sein... in den Ruinen, das ist sicher. Das Amulett wird sie... (((hustet)))... genau zu den Rollen führen, wenn sie keiner aufhält. Es ist an Euch, $N. Bitte... holt das Amulett.\n\nDie Rollen werden es den Dunkeleisenzwergen ermöglichen, noch mächtigere Golems zu erschaffen. Ich weiß es einfach. Spür's in meinen Knochen.", objectives = "Sucht Hammertoes Amulett und bringt es ihm nach Uldaman.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[723] = { title = "Ein Funken Hoffnung", description = "<Hammertoe fasst an seine Wunden und braucht einen Moment, um sich zu sammeln, bevor er weiterspricht.>\n\nFindet Ryedol, $N. Bringt ihm mein Amulett. <hustet> Er... <hustet>... wird wissen, was zu tun ist; er weiß, dass ich nach den Wurzeln unseres Volks suchte, und er... <hustet>... weiß, dass es meine Aufgabe war, den Schattenschmiedeklan aufzuhalten. Sie dürfen die Rollen nicht finden... <hustet>", objectives = "Bringt Ausgrabungsleiter Ryedol im Ödland Hammertoes Amulett.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[724] = { title = "Ein Funken Hoffnung", description = "Okay, okay... Wer könnte wissen, was zu tun ist?\n\nHistoriker Karnik! Genau!\n\nEr lebt in Ironforge. Er kann helfen. Er und Hammertoe haben zusammengearbeitet, um in Uldaman nach den verschollenen Artefakten zu suchen.\n\nSchätze, die Zwerge der Schattenschmiede haben rausgefunden, dass die beiden mehr wussten, als sie sagten.\n\nErzählt Karnik, was mit Hammertoe geschehen ist, und gebt ihm das Amulett - er wird Euch dann sagen, was als Nächstes zu tun ist.", objectives = "Bringt Historiker Karnik in Ironforge Hammertoes Amulett.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[725] = { title = "Kunde über die Bedrohung breitet sich aus", description = "$N, lauft los und findet so schnell wie möglich Berater Belgrum; sagt ihm, was Ihr gesehen habt, und fragt ihn, wie wir weiter vorgehen sollen. Diese Notiz wird ihm alles Weitere erklären.\n\nIn der Zwischenzeit werde ich mir die Zeit nehmen, um mit Hammertoes Geist zu sprechen. Vielleicht weiß er etwas, das uns helfen könnte, die Aktivitäten der Zwerge der Schattenschmiede hier im Ödland zu unterbinden. Wir können nur beten.", objectives = "Sucht Berater Belgrum und gebt ihm die Notiz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[726] = { title = "Kunde über die Bedrohung breitet sich aus", description = "<Berater Belgrum erreicht das Ende der Notiz und für einen Moment weiten sich seine Augen.>\n\nAch, das sind schlimme Nachrichten.\n\n$n, bitte kehrt zu Historiker Karnik zurück und sagt ihm, dass er im Auftrag des Königs schnell und entschlossen gemäß dieser Information handeln soll. Er muss die Aktivitäten der Zwerge der Schattenschmiede im Ödland unterbinden.", objectives = "Sprecht mit Historiker Karnik.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[727] = { title = "Auf nach Ironforge zu 'Yagyins Zusammenstellung'", description = "Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!\n\nEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Unzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!\n\nGeht zu Gerrig Bonegrip. Er befindet sich in Ironforge in einem Geschäft im düsteren Viertel. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!", objectives = "Gebt Gerrig Bonegrip im düsteren Viertel von Ironforge das Siegelzeichen des Hammers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[728] = { title = "Auf nach Undercity zu 'Yagyins Zusammenstellung'", description = "Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!\n\nEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Unzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!\n\nSucht den Bewahrer Bel'dugur in Undercity von Lordaeron auf. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!", objectives = "Bringt dem Bewahrer Bel'dugur in Undercity das Siegelzeichen des Hammers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[729] = { title = "Der geistesabwesende Ausgrabungsleiter", description = "Was war es doch für eine Ehre, als Meister Greywhisker mir auftrug, unter der Führung des großen Ausgrabungsleiters Remtravel zu arbeiten. Jeder an der Akademie in Ironforge kannte Remtravels großartige Entdeckungen.\n\nAber der Ausgrabungsleiter ist sich nicht so recht ... ähm ... bewusst ... was um ihn herum so vor sich geht.\n\nWir hatten Hinweise auf eine große Kultur entdeckt. Schreckliche Golems brachen aus dem Boden hervor und überrannten die Grabungsstätte. Remtravel schien gar nichts bemerkt zu haben. Ich rannte nach Auberdine, um Hilfe zu holen.\n\nBitte reist nach Süden und seht nach, ob es dem Ausgrabungsleiter gut geht!", objectives = "Reist nach Süden und seht nach Ausgrabungsleiter Remtravel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[730] = { title = "Ärger in Dunkelküste?", description = "Wie schön, ein $C, der an den großartigen archäologischen Wundern unserer Welt interessiert ist.\n\nOftmals wird unser Wirken von unseren Freunden der Allianz nur als reines Hobby abgetan. Aber was viele nicht einsehen wollen ist, dass die jüngsten Entdeckungen in Khaz Modan bewiesen haben, dass eine große und mächtige Kraft ganz Azeroth bedroht, von Lordaeron bis nach Kalimdor.\n\nIch bin höchst besorgt um meine Mannschaft, die ich nach Dunkelküste geschickt habe. Meine Leute haben seit Wochen nichts mehr von sich hören lassen.\n\nReist nach Auberdine und sucht nach Hinweisen auf ihren Aufenthaltsort.", objectives = "Reist nach Auberdine und sucht nach Hinweisen auf das Zwergenausgrabungsteam.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[731] = { title = "Der geistesabwesende Ausgrabungsleiter", description = "Also dann, Hollee... ach ja, richtig, Ihr seid ja gar nicht Hollee. Wo ist Hollee?\n\nPah, das ist ja jetzt auch nebensächlich. Wir müssen diesen Handfeger finden... Ich meine, das rätselhafte Fossil! Wir müssen dieses Fossil finden. Die Forscherliga in Darnassus wird ein paar Hinweise darauf haben wollen, was ich hier die ganze Zeit getrieben habe.\n\nLasst es mich wissen, wenn Ihr bereit seid, dann machen wir uns auf die Jagd nach diesem Feger... Ich meine, Fossil! Wir sollten irgendeine Niederschrift finden, damit die Liga zufrieden ist.\n\nAlso, seid Ihr so weit?", objectives = "Beschützt Ausgrabungsleiter Remtravel, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[732] = { title = "Erdbeben", description = "Ich habe von Sigrun gehört, dass Ihr ihm eine große Hilfe gewesen seid. Vielleicht darf ich Eure Hilfe ja auch in Anspruch nehmen. Mein Meister, Krasus von den Kirin Tor, hat mich hergeschickt, um die Probleme zu lösen, die sich in der Lethlorklamm zusammenbrauen.\n\nIch darf nicht preisgeben, was genau meine Mission ist oder was ich unternehmen soll, aber seid versichert, dass es von großer Wichtigkeit ist.\n\nEine Bande nomadisierender Oger, die gelegentlich in der Nähe vom Camp Boff gesichtet wurden, hat einen Gegenstand gestohlen, das so genannte \"Zeichen der Erde\", und ich muss es wiederhaben. Bringt es mir und ich verrate Euch mehr.", objectives = "Beschafft für Garek das Zeichen der Erde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[733] = { title = "Schnorrerei", description = "Es wird hier ganz schön haarig werden, wenn es mir nicht gelingt, Material aufzutreiben, um ein paar Verteidigungslinien und andere Notwendigkeiten zu konstruieren. Mir ist aufgefallen, dass die Oger in diesem Gebiet über jede Menge Metallschrott verfügen. Vielleicht sind die Geschichten über Belagerungsmaschinen im Ödland doch gar nicht so weit hergeholt...\n\nWie dem auch sei, die Ausgrabungsleiter machen sich langsam Sorgen um die Lage in unserem kleinen Lager, deshalb würde ich gern, sobald es geht, mit der Arbeit beginnen.\n\nDas Hauptlager der Oger liegt bei der Staubspeiergrotte, eine ordentliche Strecke von hier aus Richtung Westen.", objectives = "Bringt Sigrun 7 Teile Metallschrott.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[734] = { title = "Das wird schwierig", description = "Wunderbar, wunderbar.\n\n<Lotwil sieht Euch einen Moment lang an, bevor er sich wieder seinen Fesseln zuwendet.>\n\nSprecht mit Lucien, $n. Ich brauche ein Zahnrad Nr. 5. Bringt es mir bitte, ja?", objectives = "Sprecht im Ödland mit Lucien Tosselwrench.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[735] = { title = "Der Stern, die Hand und das Herz", description = "Yagyins Zusammenstellung', eh? Wollt Ihr vielleicht irgendwo eine neue Ortsgruppe aufbauen? Egal, es steht mir nicht zu, Euch das zu fragen.\n\nIch werde Euch helfen, weil ich ein Exemplar davon besitze, das ich entbehren kann. Und eine Hand wäscht die andere, stimmt's? Daher werden wir groß.\n\nIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gebe ich Euch die Zusammenstellung.\n\nIch werde ihre Namen nicht nennen. Man könnte uns belauschen. Aber wartet, ich schreibe sie auf.", objectives = "Bringt Gerrig Bonegrip in Ironforge die Gegenstände in Bonegrips Notiz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[736] = { title = "Der Stern, die Hand und das Herz", description = "Ihr braucht 'Yagyins Zusammenstellung'? Dann wollt Ihr also eine neue Herde sammeln? Natürlich... und natürlich werde ich Euch helfen, $gBruder:Schwester;.\n\nAber Ihr müsst mir auch helfen.\n\nIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gehört die Zusammenstellung Euch.\n\nIch darf die Namen dieser Gegenstände nicht aussprechen, aber ich werde sie aufschreiben.\n\nBringt mir die Gegenstände, die auf dieser Liste stehen. Wenn Ihr das schafft, seid Ihr wahrlich würdig, ein eigenes Kapitel über unseren Orden zu beginnen.", objectives = "Bringt dem Bewahrer Bel'dugur in Undercity die Gegenstände von Bel'dugurs Notiz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[737] = { title = "Verbotenes Wissen", description = "Ich habe die Zusammenstellung für Euch, $n. Ich muss Euch wohl nicht sagen, dass Ihr sie sorgfältig behandeln solltet. Und dass Ihr sie nicht in unfreundliche Hände gelangen lassen solltet. \n\nDieses Buch enthält viele Wahrheiten...\n\n... und die Wahrheit kann manchmal wehtun.", objectives = "Bringt Theldurin 'Yagyins Zusammenstellung'.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[738] = { title = "Sucht Agmond", description = "Ausgrabungsleiter Agmond hatte die Verantwortung über unsere Ausgrabungsstätten im Ödland, im Südwesten. Ich sagte \"hatte\", weil... also, ich habe schon seit Wochen nichts mehr von ihm gehört. Ich möchte, dass Ihr Agmond sucht, damit er mir Bericht erstatten kann.\n\nZuletzt hörte ich, dass sich Agmond in der südlichsten Grabungsstätte im Ödland aufhalten würde - einer winzigen Unternehmung hinter der Festung Angor. Ich würde dort mit der Suche beginnen.", objectives = "Sucht Agmond.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[739] = { title = "Murdaloc", description = "Agmonds Spuren führen nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der Zwerg ein ganzes Stück weit geschleppt haben muss.\n\nUnd hier ist er dann gestorben.\n\nBei näherer Betrachtung ist das Wort \"Murdaloc\" erkennbar, das grob aus Sandsteinen des Ödlands zusammengestückelt wurde.\n\nDirekt neben Agmonds toter Hand.", objectives = "Tötet Agmonds Mörder Murdaloc.\n\nTötet 12 Knochenknacker der Steingrufttroggs.\n\nErstattet Ausgrabungsleiter Ironband am Loch Modan Bericht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[741] = { title = "Der geistesabwesende Ausgrabungsleiter", description = "Der Ausgrabungsleiter will also das geheimnisvolle Fossil zur Forscherliga nach Darnassus schicken? Es schmeckt mir gar nicht, Dunkelküste ohne ihn zu verlassen.\n\nHier, $N, bringt Ihr dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.", objectives = "Bringt dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[742] = { title = "Die Jagd in Ashenvale", description = "Achtung, junge Abenteurer! Die Wildnis von Ashenvale erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splintertreeposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Thunderheart im Splintertreeposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd in Ashenvale teilnehmen wollen!", objectives = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[743] = { title = "Windfuriengefahr", description = "Danke, dass Ihr Euch die Zeit genommen habt, mit mir zu sprechen, $n. Ich bin Ruul, Krieger und Lehrer.\n\nIhr habt offensichtlich ein Alter erreicht, in dem Ihr Euch auf Eure Aufgaben vorbereiten müsst, wenn Ihr auf Abenteuer weit außerhalb von Mulgore aus seid.\n\nWenn Ihr Eure Kraft erproben möchtet, versucht Euch zuerst an den Windfurienharpyien im Südosten. Sie treiben sich an den Bergrändern fernab der Straße herum.\n\nSie gehören mit zu unseren natürlichen Feinden hier in Mulgore und sind gut geeignet, um Eure Fertigkeiten einzuschätzen.", objectives = "Bringt Ruul Eagletalon in Bloodhoof 8 Windfurienkrallen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[744] = { title = "Vorbereitungen auf die Zeremonie", description = "$N, mein Bruder wird schon bald vor Häuptling Bloodhoof treten und es ist mir eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen.\n\nIch möchte Euch um einen Gefallen bitten, während ich die letzten dieser Lederriemen gerbe. Ich habe keine Zeit mehr, um genügend Federn zu suchen, und ich habe mich gefragt, ob Ihr wohl noch ein paar für mich sammeln würdet?\n\nIhr könnt Federn in der richtigen Größe bei den Harpyien finden, die ganz weit im Norden und nordwestlich von Thunder Bluff leben. Ich brauche nur 6 azurblaue und 6 bronzene Federn, um die Ausführung zu vervollständigen.", objectives = "Sammelt 6 azurblaue und 6 bronzene Federn und bringt sie Eyahn Eagletalon in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[745] = { title = "Gemeinsame Nutzung des Landes", description = "Viele Konflikte verwunden dieses Land, $N. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich von Bloodhoof in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", objectives = "Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bloodhoof in Bloodhoof zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[746] = { title = "Zwergen-Buddelei", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Thunder Bluff, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", objectives = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Baine Bloodhoof in Bloodhoof 5 zerbrochene Werkzeuge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[747] = { title = "Die Jagd beginnt", description = "Ihr seht viel versprechend aus, und ich denke, Ihr werdet Euch dem Stamm gegenüber beweisen. Vielleicht wird man Euch eines Tages in der großen Stadt Thunder Bluff willkommen heißen. Bevor das jedoch möglich ist, müsst Ihr Euch meinem Vater, Häuptling Hawkwind, beweisen.\n\nWir hier oben auf der Red Cloud Mesa sind stolz auf unsere hervorragenden Jagdfertigkeiten. Tauren jagen aus Notwendigkeit und als sportlichen Wettkampf. Unsere Fleischvorräte gehen zur Neige und wir brauchen Federn, um Kleidung herzustellen. Jagt die in der Nähe herumwandernden Ebenenschreiter und beweist Euch, indem Ihr für Nachschub für das Dorf sorgt.", objectives = "Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[748] = { title = "Vergiftetes Wasser", description = "Goblins und ihre Gefolgsleute haben unsere heiligen Wasserbrunnen besudelt! Das dürfen wir nicht zulassen.\n\nUm alle Brunnen zu säubern, muss ich ein Säuberungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.\n\nZuerst werden wir ein Säuberungstotem für den Wasserbrunnen von Winterhoof herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und erwachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.\n\nKehrt mit den Tatzen und Krallen zu mir zurück, $N.", objectives = "Bringt Mull Thunderhorn in Bloodhoof 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[749] = { title = "Die Überfallene Karawane", description = "Vor ein paar Tagen haben wir am Nordufer des Stonebullsees eine bewachte Karawane der Venture Company entdeckt. Wir haben bei früheren Kämpfen mit ihnen zwei unserer Leute verloren, deshalb haben wir mit der Karawane kurzen Prozess gemacht.\n\nWir haben ihre Nachschubkisten zurückgelassen, weil wir dachten, unsere Fackeln würden alles Wertvolle zerstören, aber da man in der Nähe der ausgebrannten Wagen Bergungstrupps der Venture Company gesichtet hat, haben wir uns wohl geirrt.\n\nWürdet Ihr zur Karawane gehen und den Inhalt der Kisten untersuchen?", objectives = "Morin Cloudstalker möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[750] = { title = "Die Jagd geht weiter", description = "Ein Tauren, der in der Fertigkeit des Jagens bewandert ist, weiß, dass seine Beute nicht nur eine Trophäe ist. Die Wildtiere der Ebenen versorgen uns mit allem, was wir zum Überleben brauchen. Ihr würdet die Ältesten ziemlich beeindrucken, wenn Ihr ein paar hochgeschätzte Bergpumapelze erjagen würdet. Ihr findet die Wildtiere in den Hügeln im Süden.\n\nUnsere Kinder brauchen Kleidung und unsere Zelte müssen repariert werden.", objectives = "Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[751] = { title = "Die Überfallene Karawane", description = "Als Ihr den Deckel der Kiste aufstemmt, findet Ihr sie vollgestopft mit einem Sortiment aus Erzen und Mineralien, weitere Beweise für den Bergbau der Venture Company in Mulgore. Oben auf dem Erz und den Mineralien liegt ein fest verschnürtes Bündel Papiere, das Ihr an Euch nehmt.\n\nVom Vorgebirge im Osten her könnt Ihr schwach Arbeitsgeräusche hören und Ihr seht Rauch von einem großen Feuer aufsteigen.", objectives = "Bringt Morin Cloudstalker in der Nähe von Bloodhoof die Dokumente der Venture Company.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[752] = { title = "Eine bescheidene Bitte", description = "Alle Mitglieder des Stammes teilen die Harmonie des Lebens miteinander. Wir leben und arbeiten zusammen.\n\nMit der Verpflichtung, füreinander da zu sein, haben wir eine große Verantwortung übernommen. Ich habe eine bescheidene Bitte an Euch.\n\nMeine Mutter ist heute Morgen fortgegangen, um Wasser aus dem Brunnen südöstlich von Narache zu holen. Das ist jetzt schon eine Weile her. Würdet Ihr wohl an meiner Stelle nach ihr sehen, während ich mich hier um Stammesangelegenheiten kümmere?", objectives = "Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[753] = { title = "Eine bescheidene Bitte", description = "Ich habe in meinem Leben so viele Pfade beschritten und meinen alten Beinen mangelt es an der Energie, die sie einst hatten. Ich kann aber immer noch meine Pflichten innerhalb des Stammes erfüllen. Manchmal braucht eine alte Frau eben nur etwas länger dafür.\n\nAber Ihr scheint mir ein eifriger $C zu sein. Wir sollten Eure jugendliche Vitalität auf die Probe stellen. Holt eine Wasserkanne vom Brunnen und bringt sie meinem Sohn, dem Häuptling im Camp Narache.\n\nVergesst nicht, dass selbst die bescheidenste Tat die Anerkennung der Ahnen finden kann.", objectives = "Holt eine Wasserkanne vom Wasserbrunnen.\n\nBringt die Kanne Häuptling Hawkwind im Camp Narache, das nordwestlich des Wasserbrunnens liegt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[754] = { title = "Säuberung von Winterhoof", description = "Ich habe das Totem angefertigt, um den Wasserbrunnen von Winterhoof zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet ihn im Südosten, bewacht von elenden Goblins!\n\nDas wird keine leichte Aufgabe, aber Ihr müsst es tun, wenn wir jemals wieder sein Wasser trinken sollen.\n\nViel Glück, $N.", objectives = "Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[755] = { title = "Riten der Erdenmutter", description = "Eure Bereitschaft, für die Tauren von Narache eine bescheidene Bitte zu erfüllen, und Euer Eifer zu lernen sind edle Charakterzüge, $n. Ich weiß, eines Tages wird man in Thunder Bluff von Euch als einer bedeutenden Person sprechen, $C.\n\nBevor es so weit ist, müsst Ihr jedoch die Riten der Erdenmutter bestehen, derer es drei gibt.\n\nDie erste Prüfung ist der Ritus der Kraft. Begebt Euch zu Seher Graytongue und sagt ihm, dass Häuptling Hawkwind Euch schickt.\n\nIhr findet die Behausung des Sehers direkt südlich des Lagers Narache in den Hügeln verborgen.", objectives = "Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[756] = { title = "Thunderhorn-Totem", description = "Um das Säuberungstotem von Thunderhorn zu schaffen, benötigt Ihr die Klauen der Raubtiere der Mulgoreebene. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.\n\nIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", objectives = "Bringt Mull Thunderhorn 6 Pirscherklauen und 6 Pumaklauen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[757] = { title = "Ritus der Kraft", description = "Die Riten der Erdenmutter sind die Schritte, die ein junger Tauren gehen muss, um sich in Thunder Bluff Respekt zu verschaffen.\n\nIhr müsst zuerst den Ritus der Kraft bestehen. Bei dieser Prüfung müsst Ihr Euren Mut beweisen, indem Ihr Feinde des Stammes tötet.\n\nDer Borstennackenstamm aus der Dornrankenklamm im Osten ist in unser Stammesterritorium eingedrungen. Sie überfallen unsere Jägergruppen und rauben in der Dunkelheit unsere Dörfer aus.\n\nZeigt Euren Wagemut, indem Ihr diese Bösewichte zur Strecke bringt und dem Häuptling des Lagers Narache ihre Gürtel zum Beweis Eurer Taten vorlegt.", objectives = "Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[758] = { title = "Säuberung von Thunderhorn", description = "Das Totem ist bereit, $N. Und wiederum ist es Eure Aufgabe, das Ritual der Säuberung durchzuführen.\n\nGeht zum Wasserbrunnen von Thunderhorn nördlich des Dorfes und benutzt das Säuberungstotem von Thunderhorn bei Eurem Ritual. Kehrt danach zu mir zurück.\n\nMögen Euch die Geister leiten.", objectives = "Benutzt dasSäuberungstotem von Thunderhorn beim Wasserbrunnen von Thunderhorn und kehrt dann zu Mull zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[759] = { title = "Wildmane-Totem", description = "Es gibt nur noch einen Wasserbrunnen, der gesäubert werden muss; er trägt den Namen des Wildmaneklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.\n\nAlphatiere streifen oft am Fuße unserer mächtigen Stadt Thunder Bluff umher.", objectives = "Bringt Mull Thunderhorn in Bloodhoof 8 Präriealphazähne.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[760] = { title = "Säuberung von Wildmane", description = "Die Geister sprechen von Eurer Säuberung der Wasserbrunnen von Winterhoof und Thunderhorn, junger $N. Das Totem von Wildmane ist fertig und die letzte Aufgabe erwartet Euch.\n\nDer Wasserbrunnen von Wildmane liegt nördlich von Thunder Bluff. Führt das Ritual durch! Heilt das Land vom Gift der Goblins! Lasst das Wasser wieder klar und rein fließen!", objectives = "Benutzt das Säuberungstotem von Wildmane beim Wasserbrunnen von Wildmane und kehrt dann zu Mull Thunderhorn zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[761] = { title = "Sturzfliegerjagd", description = "Der Sturzflieger ist ein gewitzter Vogel, der schwer zu finden und zu jagen ist. Eine Sammlung Sturzfliegerkiele ist ein Zeichen der Geschicklichkeit und Entschlossenheit eines Jägers.\n\nWenn Ihr gewillt seid, diese Aufgabe anzunehmen, zieht in die Ebene hinaus und jagt die Sturzflieger.\n\nBringt mir ihre Kiele und macht Eurem Klan Ehre.\n\nSturzflieger findet man überall in Mulgore, aber Ihr müsst sehr scharfe Augen haben, um sie zu entdecken, und Ihr braucht flinke Hufe, um sie zu fangen.", objectives = "Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[762] = { title = "Ein Botschafter des Bösen", description = "Ragnaros persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach in Uldaman verschollenen Artefakten organisiert.\n\nUnser Volk hat bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert. Ich wage kaum zu schätzen, wie viele Artefakte sie finden und gegen Ironforge einsetzen könnten.\n\nUnser Ziel ist einfach, $C. Kehrt ins Ödland zurück und beseitigt den Botschafter Infernus. Sobald die Bedrohung aus der Welt geschafft ist, kehrt mit einem Beweis Eures Sieges zu Berater Belgrum zurück.\n\nEs liegt jetzt in Euren Händen.", objectives = "Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[763] = { title = "Riten der Erdenmutter", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, $n.\n\nReist nach Bloodhoof und sprecht mit Häuptling Baine Bloodhoof, dem Sohn von Cairne. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Thunder Bluff verdienen.\n\nBringt Baine dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr  könntet Euch sonst verirren.", objectives = "Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[764] = { title = "Die Venture Company", description = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.\n\nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der Überfallenen Karawane und schickt ihnen eine Nachricht.", objectives = "Tötet für Morin Cloudstalker in der Nähe von Bloodhoof 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[765] = { title = "Vorsteher Fizsprocket", description = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.\n\nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Fizsprocket, Ihr findet ihn in der Mine der Venture Co. östlich der überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", objectives = "Tötet Vorsteher Fizsprocket und bringt Morin Cloudstalker in der Nähe von Bloodhoof dessen Klemmbrett.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[766] = { title = "Mazzranach", description = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.\n\nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend wie ihn mein Großvater beschrieben hatte. Ich werde ein paar nur sehr schwer zu findende Körperteile von Tieren benötigen, um die Infektion durch seinen Biss zu säubern: ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.\n\nSchnell, Zeit ist hier entscheidend.", objectives = "Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[767] = { title = "Ritus der Sicht", description = "Der Ritus der Sicht, einer der Riten der Erdenmutter, wird Euch helfen, den Respekt der Ältesten von Thunder Bluff zu erlangen.\n\nUnser Volk hat gelernt, dass das Land unser allerheiligster Versorger ist. Um am Ritus der Sicht teilzunehmen, müsst Ihr mit dem geistigen Anführer des Dorfes sprechen, Zarlman Two-Moons.", objectives = "Sprecht in Bloodhoof mit Zarlman Two-Moons.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[768] = { title = "Leder sammeln", description = "Seid gegrüßt. Ihr habt so einen Glanz in den Augen; Ihr brennt darauf, in die Ebene zurückzukehren, um zu jagen. Möget Ihr Eurem Klan Ehre machen!\n\nIch arbeite mit den Häuten von Wildtieren und fertige daraus Kleidung und Rüstung für die Leute von Thunder Bluff.\n\nWenn Ihr Wildtiere jagt und mir ihre Häute bringt, fertige ich Euch etwas daraus.", objectives = "Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[769] = { title = "Kodobalgtasche", description = "Die Kodowildtiere von Mulgore sind stark und robust - Charaktereigenschaften, die wir sehr schätzen. Wenn Ihr in der Lederverarbeitung bewandert seid und wissen möchtet, wie man eine Kodobalgtasche fertigt, bringt mir die Materialien, die ich für mein Handwerk brauche.\n\nDann teile ich mein Wissen mit Euch.", objectives = "Bringt Veren Tallstrider in Thunder Bluff 4 Einheiten leichtes Leder und 4 grobe Fäden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[770] = { title = "Der Dämonennarbenumhang", description = "Der struppige Balg von Geistheuler trägt immer noch die schreckliche Wunde, die der Wolf im Kampf gegen die Brennende Legion davongetragen hat.\n\nVielleicht weiß jemand in Bloodhoof, wie Geistheuler starb...", objectives = "Sucht jemanden, der etwas über Geistheuler weiß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[771] = { title = "Ritus der Sicht", description = "Um den Ritus der Sicht zu bestehen, müsst Ihr die Zutaten sammeln, die für das Wasser der Seher benötigt werden:\n\nIch brauche Quellsteine, die man in der Nähe von Wasserbrunnen in Mulgore findet. Diese kombiniere ich mit Bernsteinkorn, das von den mächtigen Bäumen in unserem Land fällt.\n\nDiese Reagenzien enthalten magische Elemente, und wenn sie erhitzt und vor dem Stammesfeuer verzehrt werden, bekommt man eine Vision. Folgt ihr, dann wird sie Euch zum nächsten Schritt dieser heiligen Suche führen.", objectives = "Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[772] = { title = "Ritus der Sicht", description = "Hier ist es nun, das Wasser der Seher.\n\nWenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, wird es einen Moment dauern, bis die Vision vor dem Feuer erscheint.\n\nDann liegt es bei Euch, ihr zu Eurer Bestimmung zu folgen ...", objectives = "Trinkt vor dem Stammesfeuer in Bloodhoof das Wasser der Seher und folgt der Vision, sobald sie erscheint.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[773] = { title = "Ritus der Weisheit", description = "Um die Anerkennung der Ältesten von Thunder Bluff zu verdienen, müsst Ihr als Nächstes den Ritus der Weisheit absolvieren.\n\nJetzt, da Ihr den Ritus der Sicht bestanden habt, geben Euch die Vorfahrengeister der Teufelsfelsen den Segen unserer Vorfahren. Nur jene, die von dem Wasser der Seher getrunken haben, können diesen Segen erhalten.\n\nReist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist, $N.", objectives = "Reist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[775] = { title = "Reise nach Thunder Bluff", description = "Jetzt wird man Euch in unserer großen Stadt verehren. Ein $R, der würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nFür Eure letzte Aufgabe sucht unseren edlen Anführer Cairne Bloodhoof auf, der auf der höchsten Mesa in Thunder Bluff residiert.", objectives = "Sprecht in Thunder Bluff mit Cairne Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[776] = { title = "Riten der Erdenmutter", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Thunder Bluff verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, $n. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", objectives = "Cairne Bloodhoof in Thunder Bluff möchte, dass Ihr ihm das Horn von Arra'chea bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[777] = { title = "Das wird schwierig", description = "Bitte sehr, das ist für Euch.\n\nIch werde hier drüben sein... in Deckung.\n\nGesellt Euch ruhig zu mir.", objectives = "Bringt Lotwil Veriatus ein Zahnrad Nr. 5.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[778] = { title = "Das wird schwierig", description = "Haha! Fertig! Die Fesseln sind fertig!\n\nDer Moment ist gekommen, Lucien. Der Moment ist gekommen, Servo!\n\nSeid Ihr bereit, Zeuge der perfekten Verschmelzung von Alchimie, Ingenieurskunst und des Arkanen zu werden, $N?\n\nIch werde jetzt einen mächtigen Elementar beschwören. Das ist heute ein Bahn brechender Tag für uns alle.", objectives = "Besiegt den Fam'retor-Wächter und bringt Lotwils Fesseln der Elementarbindung zu Lotwil Veriatus zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[779] = { title = "Siegel der Erde", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[780] = { title = "Die Kampfeber", description = "Die Kampfeber der Dornrankenklamm im Osten sind in unser Stammesjagdterritorium eingedrungen. Sie wurden von den Borstennackenstachelebern, mit denen wir uns im Krieg befinden, abgerichtet, niederträchtig zu sein.\n\nTötet diese elenden Kreaturen und bringt mir ein paar ihrer Schnauzen und Flanken, damit wir daraus einen Eintopf für unsere Jungen zubereiten können.", objectives = "Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[781] = { title = "Angriff auf Camp Narache", description = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Eure Entdeckung die geheimen Pläne des Grimmhauer-Kriegshäuptlings für eine ausgedehnte Belagerung des Lagers Narache sind.\n\nHäuptling Hawkwind wird diese Informationen sicherlich gut gebrauchen können!", objectives = "Bringt Häuptling Hawkwind im Camp Narache die Angriffspläne der Borstennacken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[782] = { title = "Zerbrochene Allianzen", description = "Durch die Allianz der Horde mit dem Großdrachen Deathwing während des zweiten Krieges wissen wir, dass zwei ihrer Offiziere, Schattenbringer und Hematus, in der Lethlorklamm weit im Osten eingesperrt sind. Wir müssen unsere verderbten Verbündeten von damals zum Stillschweigen bringen, um die Ehre der Horde wiederherzustellen!\n\nWir hatten Tho'grun und seine Gruppe Ogersöldner angeheuert, damit sie uns helfen, das Zeichen der Erde in die Hände zu bekommen, ein Schlüssel, mit dem das Gefängnis des Drachen geöffnet werden kann. Tho'grun hat uns jedoch verraten, uns überrumpelt und ihn sich selbst angeeignet. Begebt Euch zum Camp Boff und holt ihn zurück!", objectives = "Tötet Tho'grun und bringt Gorn in Kargath das Zeichen der Erde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
